insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0118', 'Sport', 'Football', 'Qui marque les deux buts du Zaïre lors du match rejoué de la finale de 1974 ?', '["Ndaye Mulamba", "Kalala Mukendi", "Mwepu Ilunga", "Kidumu Mantantu"]'::jsonb, 0, 'Ndaye Mulamba inscrit un doublé.', 'https://www.cafonline.com/afcon2025/news/dr-congo-multiple-names-two-titles/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0119', 'Sport', 'Football', 'Quel pays la RDC bat-elle en finale de la CAN 1968 ?', '["Ghana", "Sénégal", "Éthiopie", "Cameroun"]'::jsonb, 0, 'Congo-Kinshasa bat le Ghana 1-0 en finale.', 'https://www.cafonline.com/afcon2025/news/dr-congo-multiple-names-two-titles/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0120', 'Sport', 'Football', 'Quel joueur marque le but de la victoire en finale de la CAN 1968 ?', '["Pierre Kalala Mukendi", "Ndaye Mulamba", "Léon Mungamuni", "Kidumu Mantantu"]'::jsonb, 0, 'Pierre Kalala Mukendi inscrit l’unique but de la finale.', 'https://www.cafonline.com/afcon2025/news/dr-congo-multiple-names-two-titles/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0121', 'Sport', 'Football', 'Combien de buts Ndaye Mulamba inscrit-il lors de la CAN 1974 ?', '["5", "7", "9", "11"]'::jsonb, 2, 'Il inscrit 9 buts pendant le tournoi.', 'https://www.cafonline.com/afcon2025/news/dr-congo-multiple-names-two-titles/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0122', 'Sport', 'Football', 'Le Zaïre participe à quelle Coupe du monde de football ?', '["1970", "1974", "1978", "1982"]'::jsonb, 1, 'Le Zaïre participe au Mondial 1974 en Allemagne de l’Ouest.', 'https://www.fifa.com/fr/tournaments/mens/worldcup/articles/plus-gros-ecarts-mi-temps', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0123', 'Sport', 'Football', 'Quel adversaire bat le Zaïre 9-0 au Mondial 1974 ?', '["Yougoslavie", "Brésil", "Écosse", "Allemagne"]'::jsonb, 0, 'La Yougoslavie bat le Zaïre 9-0.', 'https://www.fifa.com/fr/tournaments/mens/worldcup/articles/plus-gros-ecarts-mi-temps', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0124', 'Sport', 'Basket', 'Combien de fois Dikembe Mutombo a-t-il été sélectionné au NBA All-Star Game ?', '["4", "6", "8", "10"]'::jsonb, 2, 'La NBA le crédite de 8 sélections All-Star.', 'https://www.nba.com/player/87', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0125', 'Sport', 'Basket', 'Combien de points Mwadi Mabika inscrit-elle au total aux Jeux olympiques de 1996 ?', '["87", "101", "121", "143"]'::jsonb, 2, 'La FIBA indique 121 points en 7 matchs.', 'https://www.fiba.basketball/fr/history/352-womens-olympic-basketball-tournament/2547/players/116859-mwadi-marie-mabika', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0126', 'Sport', 'Basket', 'Quelle moyenne de points Mwadi Mabika affiche-t-elle aux JO 1996 ?', '["9,8", "12,4", "17,3", "22,1"]'::jsonb, 2, 'Sa moyenne officielle est de 17,3 points.', 'https://www.fiba.basketball/fr/history/352-womens-olympic-basketball-tournament/2547/players/116859-mwadi-marie-mabika', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0127', 'Sport', 'Football', 'Quel était le nom du pays lors de son premier titre continental en 1968 ?', '["Congo-Kinshasa", "Zaïre", "RDC", "Congo belge"]'::jsonb, 0, 'La CAF indique que le premier titre est remporté sous le nom de Congo-Kinshasa.', 'https://www.cafonline.com/afcon2025/news/dr-congo-multiple-names-two-titles/', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0128', 'Sport', 'Football', 'Quel pays hôte le Congo-Kinshasa bat-il en demi-finale de la CAN 1968 ?', '["Éthiopie", "Ghana", "Sénégal", "Nigeria"]'::jsonb, 0, 'Congo-Kinshasa bat l’Éthiopie 3-2 après prolongation.', 'https://www.cafonline.com/afcon2025/news/dr-congo-multiple-names-two-titles/', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0129', 'Sport', 'Football', 'Quel score termine le premier match de la finale de la CAN 1974 entre le Zaïre et la Zambie ?', '["1-0", "2-1", "2-2", "3-3"]'::jsonb, 2, 'Le premier match se termine 2-2 après prolongation.', 'https://www.cafonline.com/afcon2025/news/dr-congo-multiple-names-two-titles/', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0130', 'Sport', 'Football', 'Quel record de Ndaye Mulamba lors de la CAN 1974 est encore cité par la CAF ?', '["9 buts sur un seul tournoi", "5 passes décisives", "3 buts en finale", "6 penalties"]'::jsonb, 0, 'La CAF cite son record de 9 buts lors d’une même édition.', 'https://www.cafonline.com/afcon2025/news/dr-congo-multiple-names-two-titles/', null, null, 5, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0132', 'Institutions & politique', 'État', 'Quelle est la monnaie de la RDC selon la Constitution ?', '["Franc congolais", "Dollar congolais", "Zaïre", "Franc CFA"]'::jsonb, 0, 'La Constitution désigne le franc congolais comme monnaie nationale.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0135', 'Institutions & politique', 'Langues nationales', 'Combien de langues nationales la Constitution nomme-t-elle expressément ?', '["2", "3", "4", "5"]'::jsonb, 2, 'La Constitution nomme le kikongo, le lingala, le swahili et le tshiluba.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0136', 'Institutions & politique', 'Organisation territoriale', 'Combien d’entités provinciales composent la RDC en incluant Kinshasa ?', '["25", "26", "27", "30"]'::jsonb, 1, 'La Constitution prévoit Kinshasa plus 25 provinces, soit 26 entités provinciales.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0137', 'Institutions & politique', 'Institutions', 'Le Parlement congolais est composé de quelles deux chambres ?', '["Assemblée nationale et Sénat", "Sénat et Cour constitutionnelle", "Assemblée nationale et Gouvernement", "Conseil d’État et Sénat"]'::jsonb, 0, 'Le Parlement comprend l’Assemblée nationale et le Sénat.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0138', 'Institutions & politique', 'Gouvernement', 'Qui dirige le Gouvernement de la RDC ?', '["Le Premier ministre", "Le Président du Sénat", "Le Président de l’Assemblée nationale", "Le Procureur général"]'::jsonb, 0, 'L’article 90 dispose que le Gouvernement est dirigé par le Premier ministre, chef du Gouvernement.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0142', 'Institutions & politique', 'Élections', 'Quelle institution organise le processus électoral national ?', '["CENI", "Cour de cassation", "Conseil économique et social", "CSAC"]'::jsonb, 0, 'La Commission électorale nationale indépendante organise notamment enrôlement, vote et dépouillement.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0143', 'Institutions & politique', 'Médias', 'Quelle institution constitutionnelle veille notamment à la liberté et à la protection de la presse ?', '["CSAC", "CENI", "Sénat", "Cour des comptes"]'::jsonb, 0, 'Le Conseil supérieur de l’audiovisuel et de la communication remplit cette mission.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0144', 'Institutions & politique', 'Provinces', 'Par quelles institutions une province est-elle administrée ?', '["Une Assemblée provinciale et un Gouvernement provincial", "Un Sénat provincial et un préfet", "Une Cour provinciale et un maire", "Un Parlement provincial bicaméral"]'::jsonb, 0, 'La Constitution organise chaque province autour d’une Assemblée provinciale et d’un Gouvernement provincial.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0147', 'Institutions & politique', 'Pouvoirs', 'Les traités régulièrement conclus et publiés ont, sous condition de réciprocité, une autorité :', '["Inférieure aux lois", "Égale aux lois", "Supérieure aux lois", "Uniquement consultative"]'::jsonb, 2, 'L’article 215 prévoit une autorité supérieure à celle des lois, sous réserve de leur application par l’autre partie.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0150', 'Institutions & politique', 'Révision constitutionnelle', 'Le nombre et la durée des mandats du Président peuvent-ils faire l’objet d’une révision constitutionnelle ?', '["Oui, à majorité simple", "Oui, par décret", "Non", "Seulement par le Sénat"]'::jsonb, 2, 'La Constitution protège notamment le nombre et la durée des mandats présidentiels contre la révision.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 5, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0152', 'Nature & environnement', 'Virunga', 'Quel parc national congolais a été inscrit au patrimoine mondial dès 1979 ?', '["Virunga", "Salonga", "Garamba", "Kahuzi-Biega"]'::jsonb, 0, 'Le parc national des Virunga est inscrit en 1979.', 'https://whc.unesco.org/fr/etatsparties/cd', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0153', 'Nature & environnement', 'Okapi', 'Quel animal donne son nom à une réserve de faune inscrite au patrimoine mondial en RDC ?', '["Okapi", "Bonobo", "Gorille", "Éléphant"]'::jsonb, 0, 'La Réserve de faune à okapis est inscrite depuis 1996.', 'https://whc.unesco.org/fr/etatsparties/cd', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0154', 'Nature & environnement', 'Forêts', 'Selon la Banque mondiale, la RDC abrite quelle forêt tropicale à l’échelle mondiale ?', '["La plus petite", "La deuxième plus grande", "La quatrième plus grande", "Aucune forêt tropicale"]'::jsonb, 1, 'La Banque mondiale décrit la RDC comme abritant la deuxième plus grande forêt tropicale du monde.', 'https://www.worldbank.org/ext/en/country/drc', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0155', 'Nature & environnement', 'Patrimoine mondial', 'Lequel de ces sites n’est PAS l’un des cinq biens naturels congolais inscrits à l’UNESCO ?', '["Virunga", "Garamba", "Salonga", "Lomami"]'::jsonb, 3, 'Le parc national de la Lomami figure sur la liste indicative, mais pas encore parmi les cinq biens inscrits.', 'https://whc.unesco.org/fr/etatsparties/cd', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0156', 'Nature & environnement', 'Kahuzi-Biega', 'En quelle année le parc national de Kahuzi-Biega est-il inscrit au patrimoine mondial ?', '["1979", "1980", "1984", "1996"]'::jsonb, 1, 'Kahuzi-Biega est inscrit en 1980.', 'https://whc.unesco.org/fr/etatsparties/cd', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0157', 'Nature & environnement', 'Garamba', 'En quelle année le parc national de la Garamba est-il inscrit au patrimoine mondial ?', '["1979", "1980", "1984", "1996"]'::jsonb, 1, 'La Garamba est inscrite en 1980.', 'https://whc.unesco.org/fr/etatsparties/cd', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0158', 'Nature & environnement', 'Salonga', 'En quelle année le parc national de la Salonga est-il inscrit au patrimoine mondial ?', '["1979", "1980", "1984", "1996"]'::jsonb, 2, 'La Salonga est inscrite en 1984.', 'https://whc.unesco.org/fr/etatsparties/cd', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0160', 'Nature & environnement', 'Virunga', 'Quelle superficie approximative l’UNESCO donne-t-elle au parc national des Virunga ?', '["79 000 ha", "390 000 ha", "790 000 ha", "1,9 million ha"]'::jsonb, 2, 'L’UNESCO indique environ 790 000 hectares.', 'https://whc.unesco.org/en/list/63', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0161', 'Nature & environnement', 'Virunga', 'Quel animal endémique de la RDC est explicitement cité par l’UNESCO parmi la faune des Virunga ?', '["Okapi", "Panda géant", "Kangourou", "Lama"]'::jsonb, 0, 'L’UNESCO cite l’okapi comme espèce endémique de la RDC.', 'https://whc.unesco.org/en/list/63', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0162', 'Nature & environnement', 'Garamba', 'Quelle sous-espèce de girafe fait l’objet d’efforts particuliers de conservation à la Garamba ?', '["Girafe de Kordofan", "Girafe masaï", "Girafe réticulée", "Girafe du Cap"]'::jsonb, 0, 'L’UNESCO suit spécifiquement la population de girafes de Kordofan à la Garamba.', 'https://whc.unesco.org/fr/soc/4679', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0163', 'Nature & environnement', 'Garamba', 'Quelle sous-espèce de rhinocéros n’a plus fourni d’indice de présence à la Garamba depuis 2008 ?', '["Rhinocéros blanc du nord", "Rhinocéros noir de l’est", "Rhinocéros indien", "Rhinocéros de Java"]'::jsonb, 0, 'L’UNESCO signale l’absence d’indices de rhinocéros blanc du nord depuis 2008.', 'https://whc.unesco.org/fr/soc/4679', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0164', 'Nature & environnement', 'Garamba', 'Quelle sous-espèce de rhinocéros a commencé à être réintroduite à la Garamba en 2023 ?', '["Rhinocéros blanc du sud", "Rhinocéros noir de l’ouest", "Rhinocéros indien", "Rhinocéros de Sumatra"]'::jsonb, 0, 'Un premier groupe de rhinocéros blancs du sud a été transféré en 2023.', 'https://whc.unesco.org/fr/soc/4679', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0165', 'Nature & environnement', 'Patrimoine mondial', 'Parmi les cinq biens naturels UNESCO de la RDC, lequel est une réserve et non un parc national ?', '["Réserve de faune à okapis", "Virunga", "Garamba", "Salonga"]'::jsonb, 0, 'Quatre sont des parcs nationaux ; le cinquième est la Réserve de faune à okapis.', 'https://whc.unesco.org/fr/etatsparties/cd', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0166', 'Nature & environnement', 'Patrimoine mondial', 'Le parc national de la Lomami est actuellement :', '["Inscrit au patrimoine mondial", "Sur la liste indicative de la RDC", "Retiré de l’UNESCO", "Un site culturel UNESCO"]'::jsonb, 1, 'L’UNESCO le recense sur la liste indicative depuis 2024.', 'https://whc.unesco.org/fr/etatsparties/cd', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0167', 'Nature & environnement', 'Conservation', 'Quel organisme congolais est l’autorité de gestion des aires protégées citée par l’UNESCO ?', '["ICCN", "CENI", "BCC", "OCC"]'::jsonb, 0, 'L’Institut congolais pour la conservation de la nature est l’autorité de gestion des aires protégées.', 'https://whc.unesco.org/fr/soc/4679', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0168', 'Nature & environnement', 'Virunga', 'Quel parc ougandais est contigu aux Virunga et constitue un corridor écologique transfrontalier ?', '["Queen Elizabeth National Park", "Serengeti", "Kruger", "Amboseli"]'::jsonb, 0, 'L’UNESCO cite le Queen Elizabeth National Park en Ouganda comme aire protégée contiguë.', 'https://whc.unesco.org/en/list/63', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0169', 'Nature & environnement', 'Garamba', 'Combien de rhinocéros blancs du sud ont été transférés lors du premier groupe de réintroduction en juin 2023 ?', '["6", "10", "16", "24"]'::jsonb, 2, 'L’UNESCO indique un premier transfert de 16 spécimens.', 'https://whc.unesco.org/fr/soc/4679', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0170', 'Nature & environnement', 'Patrimoine mondial', 'Quelle chronologie est correcte pour les inscriptions UNESCO ?', '["Virunga 1979 → Kahuzi-Biega/Garamba 1980 → Salonga 1984 → Okapi 1996", "Salonga 1979 → Virunga 1980 → Okapi 1984 → Garamba 1996", "Garamba 1979 → Salonga 1980 → Virunga 1984 → Okapi 1996", "Okapi 1979 → Virunga 1980 → Garamba 1984 → Salonga 1996"]'::jsonb, 0, 'C’est l’ordre chronologique indiqué par l’UNESCO.', 'https://whc.unesco.org/fr/etatsparties/cd', null, null, 5, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0171', 'Économie & ressources', 'Ressources', 'Quels deux minerais la Banque mondiale cite-t-elle parmi les ressources exceptionnelles de la RDC ?', '["Cobalt et cuivre", "Bauxite et étain seulement", "Uranium et argent seulement", "Fer et lithium seulement"]'::jsonb, 0, 'La Banque mondiale cite notamment le cobalt et le cuivre.', 'https://www.worldbank.org/ext/en/country/drc', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0172', 'Économie & ressources', 'Énergie', 'Quel type d’énergie possède un potentiel exceptionnel en RDC selon la Banque mondiale ?', '["Hydroélectricité", "Éolien offshore uniquement", "Géothermie islandaise", "Charbon arctique"]'::jsonb, 0, 'La Banque mondiale souligne le potentiel hydroélectrique du pays.', 'https://www.worldbank.org/ext/en/country/drc', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0173', 'Économie & ressources', 'Inga', 'Le complexe d’Inga exploite principalement quelle ressource ?', '["L’énergie du fleuve Congo", "Le pétrole du lac Kivu", "Le charbon du Katanga", "Le vent côtier"]'::jsonb, 0, 'Inga est un site hydroélectrique sur le fleuve Congo.', 'https://www.worldbank.org/en/news/factsheet/2024/10/09/questions-and-answers-on-world-bank-support-for-the-democratic-republic-of-congos-afe-drc-grand-inga-development-program', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0174', 'Économie & ressources', 'Forêts', 'La RDC possède, selon la Banque mondiale :', '["La deuxième plus grande forêt tropicale du monde", "Aucune forêt équatoriale", "La plus grande forêt boréale du monde", "Seulement des savanes"]'::jsonb, 0, 'La Banque mondiale souligne l’importance mondiale de la forêt tropicale congolaise.', 'https://www.worldbank.org/ext/en/country/drc', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0175', 'Économie & ressources', 'Agriculture', 'La Banque mondiale décrit les terres arables de la RDC comme :', '["Importantes", "Inexistantes", "Entièrement désertiques", "Limitées aux villes"]'::jsonb, 0, 'La RDC dispose d’importantes terres arables.', 'https://www.worldbank.org/ext/en/country/drc', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0176', 'Économie & ressources', 'Cobalt', 'En 2025, quel pays était le premier producteur mondial de cobalt minier selon l’USGS ?', '["RDC", "Indonésie", "Canada", "Australie"]'::jsonb, 0, 'Selon le Mineral Commodity Summaries 2026 de l’USGS, la RDC représentait environ 73 % de la production minière mondiale de cobalt en 2025.', 'https://pubs.usgs.gov/periodicals/mcs2026/mcs2026-cobalt.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0177', 'Économie & ressources', 'Cobalt', 'Quelle part approximative de la production mondiale de cobalt minier provenait de RDC en 2025 selon l’USGS ?', '["53 %", "63 %", "73 %", "93 %"]'::jsonb, 2, 'L’USGS estime qu’en 2025 la RDC a fourni environ 73 % du cobalt minier mondial.', 'https://pubs.usgs.gov/periodicals/mcs2026/mcs2026-cobalt.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0178', 'Économie & ressources', 'Cobalt', 'Quel pays arrivait derrière la RDC pour la production de cobalt minier en 2025 selon l’USGS ?', '["Indonésie", "France", "Brésil", "Afrique du Sud"]'::jsonb, 0, 'En 2025, l’Indonésie était le deuxième producteur mondial, avec environ 14 % de la production minière mondiale de cobalt.', 'https://pubs.usgs.gov/periodicals/mcs2026/mcs2026-cobalt.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0179', 'Économie & ressources', 'Cobalt', 'La majorité des ressources mondiales de cobalt liées aux gisements sédimentaires cuivre-cobalt se trouve notamment en RDC et dans quel pays ?', '["Zambie", "Égypte", "Maroc", "Kenya"]'::jsonb, 0, 'L’USGS cite principalement la RDC et la Zambie pour ces ressources.', 'https://pubs.usgs.gov/periodicals/mcs2025/mcs2025.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0180', 'Économie & ressources', 'Électricité', 'Selon la Banque mondiale, quelle part de la population de la RDC avait accès à l’électricité en 2024 ?', '["22,5 %", "45 %", "67 %", "91 %"]'::jsonb, 0, 'Les données de la Banque mondiale indiquent un accès à l’électricité d’environ 22,5 % de la population en 2024.', 'https://data.worldbank.org/indicator/EG.ELC.ACCS.ZS?locations=CD', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0181', 'Économie & ressources', 'Inga', 'Le programme Grand Inga est avant tout lié à quel secteur ?', '["Hydroélectricité", "Transport aérien", "Télécommunications", "Pêche maritime"]'::jsonb, 0, 'Grand Inga est un programme de développement hydroélectrique.', 'https://www.worldbank.org/en/news/factsheet/2024/10/09/questions-and-answers-on-world-bank-support-for-the-democratic-republic-of-congos-afe-drc-grand-inga-development-program', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0182', 'Économie & ressources', 'Ressources', 'La Banque mondiale décrit-elle la RDC comme pauvre en ressources naturelles ?', '["Non", "Oui", "Uniquement en minerais", "Uniquement en eau"]'::jsonb, 0, 'Elle insiste au contraire sur l’abondance des ressources naturelles.', 'https://www.worldbank.org/ext/en/country/drc', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0183', 'Économie & ressources', 'Cobalt', 'Quel secteur mondial consomme une grande partie du cobalt raffiné, selon l’USGS ?', '["Batteries lithium-ion", "Papier journal", "Ciment", "Textile en coton"]'::jsonb, 0, 'L’USGS souligne le poids de l’industrie des batteries lithium-ion dans la consommation de cobalt.', 'https://pubs.usgs.gov/periodicals/mcs2025/mcs2025.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0184', 'Économie & ressources', 'Cobalt', 'Quel pays était en 2025 le premier producteur mondial de cobalt raffiné selon l’USGS ?', '["Chine", "RDC", "États-Unis", "Chili"]'::jsonb, 0, 'L’USGS indique que la Chine est restée en 2025 le premier producteur mondial de cobalt raffiné.', 'https://pubs.usgs.gov/periodicals/mcs2026/mcs2026-cobalt.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0185', 'Économie & ressources', 'Ressources', 'La richesse minérale congolaise a-t-elle automatiquement permis à la majorité de la population de bénéficier de cette richesse, selon la Banque mondiale ?', '["Non", "Oui", "Uniquement depuis 1960", "Uniquement à Kinshasa"]'::jsonb, 0, 'La Banque mondiale souligne que la majorité de la population n’a pas bénéficié de cette abondance de ressources.', 'https://www.worldbank.org/ext/en/country/drc', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0186', 'Économie & ressources', 'Énergie', 'Le potentiel hydroélectrique d’Inga dépend principalement de quel cours d’eau ?', '["Fleuve Congo", "Rivière Ruzizi", "Lac Tanganyika", "Rivière Ubangi uniquement"]'::jsonb, 0, 'Le site d’Inga est établi sur le fleuve Congo.', 'https://www.worldbank.org/en/news/factsheet/2024/10/09/questions-and-answers-on-world-bank-support-for-the-democratic-republic-of-congos-afe-drc-grand-inga-development-program', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0187', 'Économie & ressources', 'Cobalt', 'Quels deux pays représentaient ensemble environ 87 % de la production mondiale de cobalt minier en 2025 selon l’USGS ?', '["RDC et Indonésie", "Canada et Australie", "Chine et Russie", "Philippines et Turquie"]'::jsonb, 0, 'L’USGS estime la part de la RDC à environ 73 % et celle de l’Indonésie à environ 14 % en 2025, soit près de 87 % ensemble.', 'https://pubs.usgs.gov/periodicals/mcs2026/mcs2026-cobalt.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0188', 'Économie & ressources', 'Cobalt', 'Vers quel pays une part importante du cobalt extrait en RDC et en Indonésie est-elle acheminée pour être raffinée ?', '["Chine", "Brésil", "France", "Canada"]'::jsonb, 0, 'Les analyses de l’USGS indiquent que d’importants volumes de cobalt provenant notamment de RDC et d’Indonésie sont exportés vers la Chine pour y être raffinés.', 'https://pubs.usgs.gov/publication/sir20255021/full', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0189', 'Économie & ressources', 'Développement', 'Quel paradoxe la Banque mondiale souligne-t-elle à propos de la RDC ?', '["Une immense richesse en ressources mais une pauvreté persistante", "Une absence de ressources mais un revenu très élevé", "Une économie uniquement touristique", "Une population sans accès aux terres agricoles"]'::jsonb, 0, 'La Banque mondiale juxtapose l’abondance exceptionnelle des ressources et la pauvreté persistante.', 'https://www.worldbank.org/ext/en/country/drc', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0190', 'Économie & ressources', 'Inga', 'Quel obstacle au développement la Banque mondiale associe explicitement au faible accès à l’électricité ?', '["Un frein majeur au progrès et à la réduction de la pauvreté", "Une hausse automatique des exportations", "Une disparition des mines", "Une baisse de la biodiversité uniquement"]'::jsonb, 0, 'La Banque mondiale présente le manque d’électricité comme un frein majeur au progrès économique et social.', 'https://www.worldbank.org/en/news/factsheet/2024/10/09/questions-and-answers-on-world-bank-support-for-the-democratic-republic-of-congos-afe-drc-grand-inga-development-program', null, null, 5, 'valide') on conflict (id) do nothing;
