insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0449', 'Langues & proverbes', 'Tshiluba', 'Dans quelles provinces le tshiluba est-il particulièrement parlé selon la ressource Tshiluba.co ?', '["Kasaï, Kasaï-Central, Sankuru, Kasaï-Oriental et Lomami", "Nord-Kivu, Sud-Kivu et Ituri uniquement", "Kongo-Central uniquement", "Haut-Katanga uniquement"]'::jsonb, 0, 'La ressource cite ces cinq provinces comme principales zones d’usage.', 'https://tshiluba.co/articles/007-Greetings-And-Basic-Introductions-In-Tshiluba/fr/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0450', 'Langues & proverbes', 'Politique linguistique', 'Que dit la Constitution à propos des autres langues du pays, au-delà du français et des quatre langues nationales ?', '["Elles font partie du patrimoine culturel congolais à protéger", "Elles sont interdites dans l’espace public", "Elles doivent disparaître progressivement", "Elles n’ont aucun statut culturel"]'::jsonb, 0, 'La Constitution affirme que les autres langues du pays font partie du patrimoine culturel congolais dont l’État assure la protection.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
