insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0456', 'Gastronomie', 'Pondu', 'Quel accompagnement est explicitement cité avec le pondu dans l’étude sur Kinshasa ?', '["Haricots", "Fromage", "Pâtes italiennes", "Olives"]'::jsonb, 0, 'Le « pondu ya madesu » associe feuilles de manioc et haricots.', 'https://agris.fao.org/search/fr/records/67484ea77625988a371a0651', null, null, 2, 'valide') on conflict (id) do nothing;
