insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0462', 'Gastronomie', 'Manioc', 'Quel autre produit du manioc sert de base à la fabrication de chikwangue ?', '["Pâte de manioc rouie et défibrée", "Farine de blé", "Huile de palme uniquement", "Riz pilé"]'::jsonb, 0, 'La FAO décrit une pâte de manioc rouie, défibrée et égouttée comme base de la chikwangue.', 'https://www.fao.org/4/y9422e/y9422e0b.htm', null, null, 2, 'valide') on conflict (id) do nothing;
