insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0750', 'Art, coutumes & patrimoine', 'Provenance', 'À quoi sert une recherche de provenance muséale ?', '["Retracer les conditions d’acquisition et de transfert d’un objet", "Évaluer seulement sa beauté", "Changer son auteur", "Créer une copie numérique uniquement"]'::jsonb, 0, 'La provenance permet de documenter l’histoire de possession et les conditions d’acquisition.', 'https://www.africamuseum.be/fr/learn/provenance/luba-mask', null, null, 5, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0752', 'Institutions & politique', 'État', 'Parmi ces langues, laquelle est la langue officielle de la RDC ?', '["Lingala", "Français", "Swahili", "Tshiluba"]'::jsonb, 1, 'La Constitution fixe le français comme langue officielle de la République démocratique du Congo.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0753', 'Institutions & politique', 'État', 'Quelle est la monnaie nationale de la RDC ?', '["Franc congolais", "Franc CFA", "Dollar congolais", "Zaïre"]'::jsonb, 0, 'La Constitution désigne le franc congolais comme monnaie nationale.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0754', 'Institutions & politique', 'État', 'Quelle est la monnaie ayant cours légal comme monnaie nationale en RDC ?', '["Franc CFA", "Franc congolais", "Dollar congolais", "Zaïre"]'::jsonb, 1, 'La monnaie nationale de la RDC est le franc congolais.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0756', 'Institutions & politique', 'État', '« Debout Congolais » désigne quel symbole national de la RDC ?', '["La devise", "L’hymne national", "Le sceau de l’État", "La monnaie"]'::jsonb, 1, '« Debout Congolais » est l’hymne national de la République démocratique du Congo.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0758', 'Institutions & politique', 'État', 'Quelle formule correspond à la devise de la RDC ?', '["Unité – Travail – Progrès", "Justice – Paix – Travail", "Paix – Liberté – Travail", "Travail – Famille – Patrie"]'::jsonb, 1, 'La devise constitutionnelle de la RDC est « Justice – Paix – Travail ».', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0759', 'Institutions & politique', 'Langues nationales', 'Combien de langues nationales la Constitution nomme-t-elle ?', '["4", "2", "3", "5"]'::jsonb, 0, 'La Constitution nomme quatre langues nationales.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0760', 'Institutions & politique', 'Langues nationales', 'Combien de langues nationales sont expressément citées par la Constitution congolaise ?', '["3", "5", "4", "6"]'::jsonb, 2, 'La Constitution cite quatre langues nationales : kikongo, lingala, swahili et tshiluba.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0761', 'Institutions & politique', 'Organisation territoriale', 'Combien de provinces compte la RDC, Kinshasa comprise ?', '["26", "21", "25", "30"]'::jsonb, 0, 'La RDC compte 26 provinces, Kinshasa comprise.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0762', 'Institutions & politique', 'Organisation territoriale', 'Kinshasa comprise, combien d’entités provinciales la RDC compte-t-elle ?', '["25", "26", "24", "30"]'::jsonb, 1, 'La RDC est organisée en 25 provinces auxquelles s’ajoute la ville-province de Kinshasa, soit 26.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0763', 'Institutions & politique', 'Parlement', 'Quelles sont les deux chambres du Parlement congolais ?', '["Assemblée nationale et Sénat", "Sénat et Cour constitutionnelle", "Assemblée nationale et Gouvernement", "Sénat et Conseil d’État"]'::jsonb, 0, 'Le Parlement comprend l’Assemblée nationale et le Sénat.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0764', 'Institutions & politique', 'Parlement', 'Le Parlement congolais est bicaméral. Quelles sont ses deux chambres ?', '["Assemblée nationale et Sénat", "Assemblée nationale et Cour constitutionnelle", "Sénat et Gouvernement", "Assemblée provinciale et Sénat"]'::jsonb, 0, 'Le Parlement de la RDC comprend l’Assemblée nationale et le Sénat.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0765', 'Institutions & politique', 'Gouvernement', 'Qui dirige le Gouvernement ?', '["Le Premier ministre", "Le Président du Sénat", "Le Président de l’Assemblée nationale", "Le Procureur général"]'::jsonb, 0, 'Le Gouvernement est dirigé par le Premier ministre.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0766', 'Institutions & politique', 'Gouvernement', 'Qui est le chef du Gouvernement de la RDC ?', '["Le Président du Sénat", "Le Premier ministre", "Le Président de l’Assemblée nationale", "Le ministre de l’Intérieur"]'::jsonb, 1, 'Le Premier ministre est le chef du Gouvernement.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0770', 'Institutions & politique', 'Présidence', 'Selon la Constitution, combien de fois un mandat présidentiel peut-il être renouvelé ?', '["Sans limite", "Une seule fois", "Deux fois", "Il n’est jamais renouvelable"]'::jsonb, 1, 'Le mandat présidentiel est renouvelable une seule fois.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0773', 'Institutions & politique', 'Élections', 'Quelle institution organise les élections nationales ?', '["CENI", "CSAC", "Cour des comptes", "Conseil économique et social"]'::jsonb, 0, 'La Commission électorale nationale indépendante organise le processus électoral.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0774', 'Institutions & politique', 'Élections', 'Quelle institution indépendante est chargée d’organiser le processus électoral en RDC ?', '["CSAC", "CENI", "Cour des comptes", "Conseil économique et social"]'::jsonb, 1, 'La Commission électorale nationale indépendante (CENI) est l’institution chargée de l’organisation des élections.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0775', 'Institutions & politique', 'Médias', 'Quelle institution veille notamment à la liberté et à la protection de la presse ?', '["CSAC", "CENI", "Cour constitutionnelle", "Sénat"]'::jsonb, 0, 'Le CSAC est l’autorité constitutionnelle de régulation de l’audiovisuel et de la communication.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0776', 'Institutions & politique', 'Médias', 'Quelle institution congolaise est chargée de la régulation des médias et de la protection de la liberté de la presse ?', '["CENI", "Cour constitutionnelle", "CSAC", "Sénat"]'::jsonb, 2, 'Le Conseil supérieur de l’audiovisuel et de la communication (CSAC) intervient dans la régulation des médias.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0777', 'Institutions & politique', 'Provinces', 'Quelles institutions administrent une province ?', '["Assemblée provinciale et Gouvernement provincial", "Sénat provincial et préfet", "Cour provinciale et maire", "Parlement provincial bicaméral"]'::jsonb, 0, 'Chaque province est administrée par une Assemblée provinciale et un Gouvernement provincial.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0778', 'Institutions & politique', 'Provinces', 'Au niveau d’une province, quelles sont les deux principales institutions politiques prévues par la Constitution ?', '["Assemblée provinciale et Gouvernement provincial", "Sénat provincial et préfet", "Conseil municipal et Cour provinciale", "Assemblée nationale et Gouverneur"]'::jsonb, 0, 'Chaque province dispose d’une Assemblée provinciale et d’un Gouvernement provincial.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0783', 'Institutions & politique', 'Traités', 'Quelle autorité les traités régulièrement conclus et publiés peuvent-ils avoir sur les lois ?', '["Supérieure", "Inférieure", "Toujours égale", "Aucune"]'::jsonb, 0, 'L’article 215 leur reconnaît une autorité supérieure à celle des lois sous conditions.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0784', 'Institutions & politique', 'Traités', 'Sous les conditions prévues par la Constitution, quelle autorité un traité régulièrement conclu et publié peut-il avoir par rapport à une loi nationale ?', '["Une autorité inférieure", "Une autorité supérieure", "Aucune autorité juridique", "Une autorité seulement consultative"]'::jsonb, 1, 'Les traités et accords internationaux régulièrement conclus ont, sous les conditions constitutionnelles, une autorité supérieure à celle des lois.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0786', 'Institutions & politique', 'Autorité coutumière', 'Quelle affirmation décrit correctement la place de l’autorité coutumière dans la Constitution congolaise ?', '["Elle n’est reconnue qu’en période électorale", "Elle est reconnue par la Constitution", "Elle n’existe qu’à Kinshasa", "Elle remplace les institutions provinciales"]'::jsonb, 1, 'La Constitution reconnaît l’autorité coutumière dans le respect de la Constitution et des lois.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0788', 'Institutions & politique', 'Compétences', 'Dans une matière relevant des compétences concurrentes, quelle norme prévaut en cas d’incompatibilité avec un édit provincial ?', '["La coutume locale", "L’édit provincial", "La législation nationale", "La décision communale"]'::jsonb, 2, 'En cas d’incompatibilité dans une matière concurrente, la législation nationale prévaut.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0789', 'Institutions & politique', 'Révision constitutionnelle', 'Le nombre et la durée des mandats présidentiels peuvent-ils être révisés ?', '["Non", "Oui à majorité simple", "Oui par décret", "Oui par référendum local"]'::jsonb, 0, 'La Constitution protège notamment ces éléments contre la révision.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0790', 'Institutions & politique', 'Révision constitutionnelle', 'Lequel de ces éléments fait partie des dispositions que la Constitution interdit de réviser ?', '["Le nombre et la durée des mandats présidentiels", "Le nombre de ministères", "Le nom des communes", "Le siège d’une entreprise publique"]'::jsonb, 0, 'La Constitution protège notamment le nombre et la durée des mandats du Président de la République contre la révision.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 5, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0791', 'Institutions & politique', 'Kinshasa', 'Quel statut territorial possède Kinshasa ?', '["Ville-province", "Territoire", "District", "Commune autonome hors province"]'::jsonb, 0, 'Kinshasa a rang de province.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0792', 'Institutions & politique', 'Kinshasa', 'Quel statut particulier possède Kinshasa dans l’organisation territoriale de la RDC ?', '["Territoire fédéral", "Ville-province", "District autonome", "Commune hors province"]'::jsonb, 1, 'Kinshasa possède le statut de ville-province.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0793', 'Institutions & politique', 'Souveraineté', 'De qui émane le pouvoir en RDC selon la Constitution ?', '["Du peuple", "Du Sénat", "De l’armée", "Des gouverneurs"]'::jsonb, 0, 'La souveraineté nationale appartient au peuple.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0794', 'Institutions & politique', 'Souveraineté', 'Selon la Constitution congolaise, de qui émane le pouvoir d’État ?', '["Du Gouvernement", "Du Parlement", "Du peuple", "Des gouverneurs"]'::jsonb, 2, 'La Constitution affirme que tout pouvoir émane du peuple.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0796', 'Institutions & politique', 'Justice', 'Quel principe constitutionnel caractérise le pouvoir judiciaire par rapport aux pouvoirs législatif et exécutif ?', '["La subordination", "L’indépendance", "La fusion", "La tutelle du Parlement"]'::jsonb, 1, 'Le pouvoir judiciaire est indépendant du pouvoir législatif et du pouvoir exécutif.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0797', 'Institutions & politique', 'Parlement', 'Qui vote les lois nationales ?', '["Le Parlement", "La CENI", "Le CSAC", "Les gouverneurs seuls"]'::jsonb, 0, 'Le pouvoir législatif national appartient au Parlement.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0798', 'Institutions & politique', 'Parlement', 'Quelle institution adopte les lois nationales en RDC ?', '["La CENI", "Le Parlement", "Le CSAC", "Les gouvernements provinciaux"]'::jsonb, 1, 'Le pouvoir législatif national est exercé par le Parlement.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-0800', 'Institutions & politique', 'Décentralisation', 'Quelle affirmation est correcte concernant les compétences des provinces en RDC ?', '["Elles n’exercent que des compétences prêtées par les communes", "Elles disposent de compétences propres prévues par la Constitution", "Elles n’ont aucune compétence normative", "Seule Kinshasa possède des compétences provinciales"]'::jsonb, 1, 'La Constitution attribue aux provinces des compétences exclusives ainsi que des compétences concurrentes avec le pouvoir central.', 'https://www.presidence.cd/uploads/files/Constitution%20de%20la%20RDC%20%202011.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
