insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1161', 'Histoire', 'Drapeaux de la RDC', 'Combien de versions successives du drapeau national la RDC a-t-elle utilisées depuis l’indépendance de 1960 ?', '["7", "5", "6", "8"]'::jsonb, 0, 'La galerie officielle distingue sept périodes depuis 1960 : 1960-1963, 1963-1966, 1966-1971, 1971-1997, 1997-2003, 2003-2006 et depuis 2006.', 'https://www.presidence.cd/uploads/files/5af308bdec9e1947e26657633ee95550.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1162', 'Histoire', 'Drapeaux de la RDC', 'Depuis l’indépendance de 1960, combien de fois le Congo/RDC a-t-il changé de drapeau national ?', '["6 fois", "5 fois", "7 fois", "8 fois"]'::jsonb, 0, 'Sept versions successives correspondent à six changements de drapeau.', 'https://www.presidence.cd/uploads/files/5af308bdec9e1947e26657633ee95550.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1163', 'Histoire', 'Drapeaux de la RDC', 'Quel drapeau la République du Congo-Léopoldville utilisait-elle entre 1960 et 1963 ?', '["Un fond bleu avec une grande étoile jaune et six petites étoiles", "Un fond vert avec une main et une torche", "Un tricolore vert-jaune-rouge", "Un fond blanc avec une étoile rouge"]'::jsonb, 0, 'Le drapeau de 1960-1963 reprenait le fond bleu avec une grande étoile et six petites étoiles représentant les provinces.', 'https://www.presidence.cd/uploads/files/5af308bdec9e1947e26657633ee95550.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1164', 'Histoire', 'Drapeaux de la RDC', 'Quel type de drapeau apparaît en 1963 ?', '["Fond bleu, étoile jaune et bande diagonale rouge bordée de jaune", "Fond vert avec torche", "Fond bleu avec six petites étoiles uniquement", "Tricolore vertical"]'::jsonb, 0, 'Le modèle de 1963 introduit l’étoile jaune et la bande rouge diagonale bordée de jaune.', 'https://www.presidence.cd/uploads/files/5af308bdec9e1947e26657633ee95550.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1165', 'Histoire', 'Drapeaux de la RDC', 'Quelle période correspond au drapeau de la République démocratique du Congo avant le Zaïre ?', '["1966-1971", "1960-1963", "1971-1997", "1997-2003"]'::jsonb, 0, 'La galerie officielle distingue le drapeau de la RDC de 1966 à 1971.', 'https://www.presidence.cd/uploads/files/5af308bdec9e1947e26657633ee95550.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1166', 'Histoire', 'Drapeaux de la RDC', 'Quel drapeau est associé à la République du Zaïre ?', '["Fond vert, disque jaune et bras tenant une torche rouge", "Fond bleu avec six étoiles", "Fond rouge avec étoile jaune", "Fond blanc avec léopard"]'::jsonb, 0, 'Le drapeau zaïrois de 1971-1997 était vert, avec au centre un disque jaune contenant une main tenant une torche.', 'https://www.presidence.cd/uploads/files/5af308bdec9e1947e26657633ee95550.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1167', 'Histoire', 'Drapeaux de la RDC', 'Quel drapeau revient après la chute de Mobutu en 1997 ?', '["Un drapeau inspiré de celui de l’indépendance avec six petites étoiles", "Le drapeau vert du Zaïre", "Le drapeau belge", "Un drapeau rouge et noir"]'::jsonb, 0, 'De 1997 à 2003, la RDC revient à un drapeau inspiré de celui de 1960.', 'https://www.presidence.cd/uploads/files/5af308bdec9e1947e26657633ee95550.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1168', 'Histoire', 'Drapeaux de la RDC', 'Entre quelles années la RDC utilise-t-elle une version bleu clair avec une grande étoile et six petites étoiles avant le drapeau actuel ?', '["2003-2006", "1990-1994", "1966-1971", "2006-2011"]'::jsonb, 0, 'La galerie officielle distingue une version spécifique utilisée de 2003 à 2006.', 'https://www.presidence.cd/uploads/files/5af308bdec9e1947e26657633ee95550.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1169', 'Histoire', 'Drapeaux de la RDC', 'Depuis quelle année le drapeau actuel de la RDC est-il utilisé ?', '["2006", "1997", "2003", "2011"]'::jsonb, 0, 'Le drapeau actuel est en usage depuis 2006.', 'https://www.presidence.cd/uploads/files/5af308bdec9e1947e26657633ee95550.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1170', 'Histoire', 'Drapeaux de la RDC', 'Avant l’indépendance, quel même emblème a servi successivement à l’Association internationale africaine, à l’État indépendant du Congo et au Congo belge ?', '["Un fond bleu foncé avec une étoile jaune centrale", "Le drapeau vert du Zaïre", "Le drapeau actuel", "Un tricolore belge modifié"]'::jsonb, 0, 'La Présidence indique que le premier drapeau, bleu foncé avec étoile jaune, a été utilisé de 1877 à 1960.', 'https://www.presidence.cd/uploads/files/5af308bdec9e1947e26657633ee95550.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1171', 'Histoire', 'Zaïre', 'En quelle année la République démocratique du Congo devient-elle officiellement la République du Zaïre ?', '["1971", "1965", "1973", "1990"]'::jsonb, 0, 'Le pays prend le nom de République du Zaïre en 1971.', 'https://www.gov.uk/government/publications/country-names/timeline-of-country-name-changes-in-hmg-use-1919-to-present', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1172', 'Histoire', 'Zaïre', 'À quelle date le pays est-il officiellement rebaptisé République du Zaïre ?', '["27 octobre 1971", "30 juin 1960", "30 novembre 1973", "17 mai 1997"]'::jsonb, 0, 'Le changement de nom est officialisé le 27 octobre 1971.', 'https://www.cia.gov/readingroom/document/cia-rdp79-00927a009600060001-1', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1173', 'Histoire', 'Zaïre', 'Pendant combien de temps environ le pays a-t-il porté le nom de Zaïre ?', '["Près de 26 ans", "5 ans", "10 ans", "40 ans"]'::jsonb, 0, 'Le nom Zaïre est utilisé de 1971 jusqu’au retour au nom République démocratique du Congo en 1997.', 'https://www.gov.uk/government/publications/country-names/timeline-of-country-name-changes-in-hmg-use-1919-to-present', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1174', 'Histoire', 'Zaïre', 'Qui décide de rebaptiser le pays « Zaïre » ?', '["Mobutu Sese Seko", "Patrice Lumumba", "Joseph Kasa-Vubu", "Laurent-Désiré Kabila"]'::jsonb, 0, 'Le changement de nom s’inscrit dans la politique d’authenticité de Mobutu.', 'https://www.presidence.cd/ancien-president-infos/5', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1175', 'Histoire', 'Zaïrianisation', 'Qu’appelle-t-on la « zaïrianisation » économique ?', '["Le transfert à des Zaïrois ou à l’État de nombreux biens et entreprises jusque-là détenus par des étrangers", "La création du franc congolais", "La suppression des provinces", "La privatisation totale des mines"]'::jsonb, 0, 'La zaïrianisation vise notamment le transfert d’entreprises, commerces, plantations et autres actifs détenus par des étrangers.', 'https://documents.worldbank.org/curated/en/987951468234892249/pdf/8210SR0v10FREN101Official0Use0Only1.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1176', 'Histoire', 'Zaïrianisation', 'Qui met en œuvre la politique de zaïrianisation ?', '["Mobutu Sese Seko", "Joseph Kasa-Vubu", "Moïse Tshombe", "Laurent-Désiré Kabila"]'::jsonb, 0, 'La zaïrianisation est une politique du régime de Mobutu.', 'https://documents.worldbank.org/curated/en/987951468234892249/pdf/8210SR0v10FREN101Official0Use0Only1.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1177', 'Histoire', 'Zaïrianisation', 'À quelle date Mobutu annonce-t-il la grande vague de zaïrianisation économique ?', '["30 novembre 1973", "27 octobre 1971", "24 novembre 1965", "17 mai 1997"]'::jsonb, 0, 'Le 30 novembre 1973, Mobutu annonce la zaïrianisation de secteurs comme l’agriculture, le commerce et les transports.', 'https://documents.worldbank.org/curated/en/987951468234892249/pdf/8210SR0v10FREN101Official0Use0Only1.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1178', 'Histoire', 'AFDL', 'Combien de dirigeants sont associés à la fondation de l’AFDL en octobre 1996 ?', '["4", "3", "5", "7"]'::jsonb, 0, 'L’AFDL est formée par quatre mouvements dirigés par Kabila, Bugera, Masasu Nindaga et Kisase Ngandu.', 'https://www.hrw.org/reports/1997/congo2/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1179', 'Histoire', 'AFDL', 'Quel compagnon de Laurent-Désiré Kabila dirigeait l’Alliance démocratique des peuples (ADP) ?', '["Déogratias Bugera", "André Kisase Ngandu", "Anselme Masasu Nindaga", "Pierre Mulele"]'::jsonb, 0, 'Déogratias Bugera dirigeait l’ADP et devient secrétaire général de l’AFDL.', 'https://www.hrw.org/reports/1997/congo2/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1180', 'Histoire', 'AFDL', 'Quel compagnon de Kabila dirigeait le Mouvement révolutionnaire pour la libération du Zaïre (MRLZ) ?', '["Anselme Masasu Nindaga", "Déogratias Bugera", "André Kisase Ngandu", "Étienne Tshisekedi"]'::jsonb, 0, 'Anselme Masasu Nindaga dirigeait le MRLZ.', 'https://www.hrw.org/reports/1997/congo2/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1181', 'Histoire', 'AFDL', 'Quel compagnon de Kabila dirigeait le Conseil national de résistance pour la démocratie (CNRD) ?', '["André Kisase Ngandu", "Déogratias Bugera", "Anselme Masasu Nindaga", "Jean-Pierre Bemba"]'::jsonb, 0, 'André Kisase Ngandu dirigeait le CNRD.', 'https://www.hrw.org/reports/1997/congo2/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1182', 'Histoire', 'AFDL', 'Les trois cofondateurs de l’AFDL aux côtés de Laurent-Désiré Kabila sont :', '["Déogratias Bugera, Anselme Masasu Nindaga et André Kisase Ngandu", "Mobutu, Kasa-Vubu et Tshombe", "Kagame, Museveni et Mandela", "Mulele, Gizenga et Tshisekedi"]'::jsonb, 0, 'Ces trois dirigeants, avec Kabila, représentent les quatre mouvements fondateurs de l’AFDL.', 'https://www.lemonde.fr/archives/article/2001/02/10/ces-enfants-soldats-qui-ont-tue-kabila_4181002_1819218.html', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1183', 'Histoire', 'AFDL', 'À quelle date les bases de l’AFDL sont-elles jetées ?', '["18 octobre 1996", "17 mai 1997", "30 juin 1960", "4 mai 1997"]'::jsonb, 0, 'L’AFDL est constituée le 18 octobre 1996.', 'https://www.hrw.org/reports/1997/congo2/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1184', 'Histoire', 'Fin du régime Mobutu', 'À quelle date Mobutu et Laurent-Désiré Kabila se rencontrent-ils directement sous médiation sud-africaine ?', '["4 mai 1997", "17 mai 1997", "30 juin 1997", "18 octobre 1996"]'::jsonb, 0, 'La rencontre directe a lieu le 4 mai 1997.', 'https://tpy.nelsonmandela.org/pages/part-v-africa-and-the-world/15-africa-focus-on-the-south/15-8-zaire-drc', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1185', 'Histoire', 'Fin du régime Mobutu', 'Sur quel navire Mobutu et Kabila se rencontrent-ils en mai 1997 ?', '["L’Outeniqua", "Le Lusitania", "Le Mobutu Sese Seko", "Le Mandela"]'::jsonb, 0, 'Les discussions ont lieu à bord du navire sud-africain Outeniqua.', 'https://tpy.nelsonmandela.org/pages/part-v-africa-and-the-world/15-africa-focus-on-the-south/15-8-zaire-drc', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1186', 'Histoire', 'Fin du régime Mobutu', 'Quel chef d’État joue un rôle majeur de médiateur entre Mobutu et Kabila en 1997 ?', '["Nelson Mandela", "François Mitterrand", "Julius Nyerere", "Kwame Nkrumah"]'::jsonb, 0, 'Le président sud-africain Nelson Mandela facilite les pourparlers.', 'https://tpy.nelsonmandela.org/pages/part-v-africa-and-the-world/15-africa-focus-on-the-south/15-8-zaire-drc', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1187', 'Histoire', 'Fin du régime Mobutu', 'Dans quel port ont lieu les discussions Mobutu-Kabila du 4 mai 1997 ?', '["Pointe-Noire", "Matadi", "Mombasa", "Durban"]'::jsonb, 0, 'Les entretiens ont lieu à bord d’un navire sud-africain au port de Pointe-Noire, à l’embouchure du fleuve Congo.', 'https://tpy.nelsonmandela.org/pages/part-v-africa-and-the-world/15-africa-focus-on-the-south/15-8-zaire-drc', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1188', 'Congo contemporain', 'Numérique', 'En quelle année la RDC s’est-elle dotée de son Code du numérique ?', '["2023", "2018", "2020", "2025"]'::jsonb, 0, 'L’ordonnance-loi n° 23/010 portant Code du numérique date du 13 mars 2023.', 'https://droitnumerique.cd/code-du-numerique-congolais-rdc-pdf/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1189', 'Congo contemporain', 'Numérique', 'Le Code du numérique congolais couvre notamment quel domaine ?', '["La sécurité et la protection pénale des systèmes informatiques", "Uniquement l’agriculture", "Uniquement le football", "Uniquement les douanes"]'::jsonb, 0, 'Le Code du numérique encadre notamment les activités numériques, contenus numériques et la sécurité des systèmes informatiques.', 'https://droitnumerique.cd/code-du-numerique-congolais-rdc-pdf/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1190', 'Congo contemporain', 'Numérique', 'Quelle institution le Code du numérique prévoit-il notamment pour la cybersécurité ?', '["Une Agence nationale de cybersécurité", "Une Banque nationale de cybersécurité", "Un Sénat numérique", "Une Police monétaire"]'::jsonb, 0, 'Le Code prévoit notamment une Agence nationale de cybersécurité parmi les autorités du secteur numérique.', 'https://droitnumerique.cd/regulation-du-numerique-en-rdc-larptic-investie-autorite-unique-pour-la-regulation-du-numerique-la-certification-electronique-et-la-protection-des-donnees/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1191', 'Congo contemporain', 'Démographie', 'Quelle population totale l’ONU estime-t-elle pour la RDC en 2025 ?', '["Environ 112,8 millions d’habitants", "Environ 60 millions", "Environ 85 millions", "Environ 150 millions"]'::jsonb, 0, 'UNData donne une estimation de 112,832 millions d’habitants en 2025.', 'https://data.un.org/fr/iso/cd.html', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1192', 'Congo contemporain', 'Démographie', 'En 2025, la RDC compte légèrement plus de femmes ou d’hommes selon l’ONU ?', '["De femmes", "D’hommes", "Exactement autant", "Impossible à estimer"]'::jsonb, 0, 'Le rapport de masculinité est de 98,5 hommes pour 100 femmes, soit environ 56,8 millions de femmes contre 56,0 millions d’hommes sur la base de l’estimation totale 2025.', 'https://data.un.org/fr/iso/cd.html', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1193', 'Histoire', 'Catastrophes', 'Quel accident aérien majeur frappe un marché de Kinshasa le 8 janvier 1996 ?', '["Le crash d’un Antonov An-32 après une sortie de piste à Ndolo", "Le crash du Concorde", "La chute d’un hélicoptère présidentiel", "Une collision de deux Boeing au-dessus de Goma"]'::jsonb, 0, 'Un Antonov An-32 rate son décollage à l’aéroport de Ndolo et termine sa course dans un marché de Kinshasa.', 'https://www.lemonde.fr/archives/article/1996/01/10/le-crash-d-un-avion-cargo-sur-un-marche-au-zaire-fait-pres-de-250-morts_3707876_1819218.html', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1194', 'Histoire', 'Catastrophes', 'Combien de morts environ le crash du marché de Kinshasa de janvier 1996 a-t-il fait selon les premières estimations rapportées par Le Monde ?', '["Environ 250", "Environ 25", "Environ 50", "Environ 1 000"]'::jsonb, 0, 'Le Monde rapporte à l’époque près de 250 morts ; les bilans varient selon les sources.', 'https://www.lemonde.fr/archives/article/1996/01/10/le-crash-d-un-avion-cargo-sur-un-marche-au-zaire-fait-pres-de-250-morts_3707876_1819218.html', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1195', 'Histoire', 'Catastrophes', 'Quelle catastrophe naturelle majeure frappe Goma le 17 janvier 2002 ?', '["L’éruption du Nyiragongo", "Un tsunami", "Un cyclone tropical", "Un tremblement de terre sans éruption"]'::jsonb, 0, 'Le Nyiragongo entre en éruption et des coulées de lave traversent Goma.', 'https://peacekeeping.un.org/fr/news/la-monusco-fournit-des-equipements-a-lobservatoire-volcanologique-de-goma', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1196', 'Histoire', 'Catastrophes', 'Combien de personnes environ l’éruption du Nyiragongo de 2002 a-t-elle laissées sans abri selon l’UNOPS ?', '["Environ 130 000", "Environ 13 000", "Environ 1 300", "Environ 500 000"]'::jsonb, 0, 'L’UNOPS indique qu’environ 130 000 personnes se sont retrouvées sans abri après l’éruption.', 'https://www.unops.org/fr/news-and-stories/stories/unops20-monitoring-volcanoes-in-the-democratic-republic-of-the-congo', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1197', 'Histoire', 'État indépendant du Congo', 'À quelle période historique est principalement associé le scandale des « mains coupées » au Congo ?', '["À l’État indépendant du Congo de Léopold II", "À la présidence de Kasa-Vubu", "À la Deuxième République", "À la période de l’AFDL"]'::jsonb, 0, 'Les mutilations documentées sont surtout associées au système coercitif de l’État indépendant du Congo, propriété personnelle de Léopold II entre 1885 et 1908.', 'https://www.gutenberg.org/ebooks/50573', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1198', 'Histoire', 'État indépendant du Congo', 'Quelle ressource est au cœur du système de coercition dénoncé lors du scandale des mains coupées ?', '["Le caoutchouc", "Le pétrole", "Le coton", "L’uranium"]'::jsonb, 0, 'La collecte forcée du caoutchouc est au cœur d’une grande partie des abus dénoncés à la fin du XIXe et au début du XXe siècle.', 'https://www.gutenberg.org/ebooks/50573', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1199', 'Histoire', 'État indépendant du Congo', 'Pourquoi des mains coupées étaient-elles parfois rapportées par des soldats ou sentinelles dans l’État indépendant du Congo ?', '["Pour justifier l’utilisation de cartouches et comme preuve de répression", "Pour payer un impôt officiel en nature", "Pour voter lors des élections", "Pour obtenir des terres agricoles"]'::jsonb, 0, 'Le rapport Casement et des témoignages contemporains documentent l’usage de mains comme preuve liée aux cartouches tirées ; les mutilations pouvaient toucher des morts comme des personnes vivantes.', 'https://onemorevoice.org/html/transcriptions/liv_020060_TEI.html', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1200', 'Histoire', 'État indépendant du Congo', 'Quel diplomate britannique mène une enquête célèbre sur les abus au Congo au début du XXe siècle ?', '["Roger Casement", "Winston Churchill", "Charles de Gaulle", "Dag Hammarskjöld"]'::jsonb, 0, 'Roger Casement enquête au Congo en 1903 et son rapport est publié en 1904.', 'https://www.cambridge.org/core/journals/journal-of-african-history/article/abs/roger-casement-and-the-congo/E871E6F598AE1657ECBCCACFCAD2B00B', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1201', 'Histoire', 'État indépendant du Congo', 'En quelle année le rapport Casement sur les abus au Congo est-il publié ?', '["1904", "1885", "1908", "1920"]'::jsonb, 0, 'Le rapport officiel de Roger Casement est publié en 1904.', 'https://www.gutenberg.org/ebooks/50573', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1203', 'Congo contemporain', 'Kuluna', 'À Kinshasa, que désigne principalement le terme « kuluna » ?', '["Des membres de gangs criminels organisés", "Des agents de la circulation", "Des joueurs de football", "Des commerçants ambulants"]'::jsonb, 0, 'Human Rights Watch utilise le terme pour désigner des membres de gangs criminels organisés à Kinshasa.', 'https://www.hrw.org/fr/report/2014/11/17/operation-likofi/meurtres-et-disparitions-forcees-aux-mains-de-la-police-kinshasa', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1204', 'Congo contemporain', 'Kuluna', 'À partir de quelle période le phénomène récent des kulunas est-il particulièrement signalé à Kinshasa ?', '["Autour des élections de 2006", "Dans les années 1930", "Uniquement après 2020", "En 1960"]'::jsonb, 0, 'Human Rights Watch situe l’apparition du phénomène kuluna contemporain autour des élections nationales de 2006.', 'https://www.hrw.org/fr/report/2014/11/17/operation-likofi/meurtres-et-disparitions-forcees-aux-mains-de-la-police-kinshasa', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1205', 'Congo contemporain', 'Kuluna', 'Quelles armes sont fréquemment associées aux kulunas dans les rapports sur Kinshasa ?', '["Machettes, couteaux et bouteilles cassées", "Chars de combat", "Missiles", "Arcs uniquement"]'::jsonb, 0, 'HRW cite notamment machettes, couteaux et tessons ou bouteilles cassées.', 'https://www.hrw.org/fr/report/2014/11/17/operation-likofi/meurtres-et-disparitions-forcees-aux-mains-de-la-police-kinshasa', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1206', 'Congo contemporain', 'Kuluna', 'Quel était l’objectif déclaré de l’Opération Likofi lancée en 2013 ?', '["Lutter contre les gangs kulunas et la criminalité urbaine", "Organiser les élections", "Nettoyer les rues de Kinshasa", "Réformer la monnaie"]'::jsonb, 0, 'L’opération policière visait officiellement à combattre les gangs kulunas et la criminalité à Kinshasa.', 'https://www.hrw.org/fr/report/2014/11/17/operation-likofi/meurtres-et-disparitions-forcees-aux-mains-de-la-police-kinshasa', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1207', 'Congo contemporain', 'Kuluna', 'À quelle date l’Opération Likofi est-elle lancée ?', '["15 novembre 2013", "15 novembre 2006", "1er janvier 2014", "30 juin 2013"]'::jsonb, 0, 'L’opération débute le 15 novembre 2013.', 'https://www.hrw.org/fr/report/2014/11/17/operation-likofi/meurtres-et-disparitions-forcees-aux-mains-de-la-police-kinshasa', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1208', 'Congo contemporain', 'Kuluna', 'Quel président avait publiquement demandé en 2013 une réponse à la criminalité des gangs à Kinshasa ?', '["Joseph Kabila", "Laurent-Désiré Kabila", "Mobutu Sese Seko", "Joseph Kasa-Vubu"]'::jsonb, 0, 'L’Opération Likofi intervient sous la présidence de Joseph Kabila.', 'https://www.hrw.org/fr/report/2014/11/17/operation-likofi/meurtres-et-disparitions-forcees-aux-mains-de-la-police-kinshasa', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1209', 'Congo contemporain', 'Kuluna', 'Combien de temps environ la première phase de l’Opération Likofi a-t-elle duré ?', '["Trois mois", "Une semaine", "Un an", "Cinq ans"]'::jsonb, 0, 'Likofi I s’étend de novembre 2013 à février 2014.', 'https://www.hrw.org/fr/report/2014/11/17/operation-likofi/meurtres-et-disparitions-forcees-aux-mains-de-la-police-kinshasa', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1210', 'Congo contemporain', 'Kuluna', 'Combien de jeunes hommes et garçons Human Rights Watch dit-elle avoir documenté comme tués lors de l’Opération Likofi ?', '["Au moins 51", "5", "150", "500"]'::jsonb, 0, 'HRW a documenté au moins 51 exécutions extrajudiciaires dans le cadre de l’opération.', 'https://www.hrw.org/fr/report/2014/11/17/operation-likofi/meurtres-et-disparitions-forcees-aux-mains-de-la-police-kinshasa', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1211', 'Congo contemporain', 'Kuluna', 'Combien de disparitions forcées Human Rights Watch dit-elle avoir documentées pendant l’Opération Likofi ?', '["33", "3", "51", "130"]'::jsonb, 0, 'HRW documente 33 disparitions forcées.', 'https://www.hrw.org/fr/report/2014/11/17/operation-likofi/meurtres-et-disparitions-forcees-aux-mains-de-la-police-kinshasa', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1212', 'Congo contemporain', 'Kuluna', 'Que signifie « Likofi » en lingala dans le nom de l’opération policière ?', '["Coup de poing", "Paix", "Justice", "Route"]'::jsonb, 0, 'Human Rights Watch traduit « Likofi » par coup de poing ou poing.', 'https://www.hrw.org/fr/report/2014/11/17/operation-likofi/meurtres-et-disparitions-forcees-aux-mains-de-la-police-kinshasa', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1213', 'Congo contemporain', 'Corruption', 'Quel montant annuel de pertes liées à la corruption et aux détournements Luzolo Bambi avançait-il publiquement en 2018 ?', '["Au moins 15 milliards USD", "1 milliard USD", "500 millions USD", "50 milliards USD"]'::jsonb, 0, 'En juin 2018, Luzolo Bambi, alors conseiller spécial du chef de l’État en matière de bonne gouvernance, a réaffirmé une estimation d’au moins 15 milliards USD par an.', 'https://www.radiookapi.net/node/182848', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1214', 'Congo contemporain', 'Corruption', 'Le chiffre de 15 milliards USD de pertes annuelles en RDC doit être compris comme :', '["Une estimation publiquement avancée par un responsable congolais en 2018", "Un montant audité chaque année par la Cour pénale internationale", "Le budget officiel de la RDC", "Le montant exact des recettes minières"]'::jsonb, 0, 'Le chiffre est une estimation attribuée à Luzolo Bambi et ne doit pas être présenté comme un montant comptable définitivement établi pour chaque année.', 'https://www.radiookapi.net/node/182848', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1215', 'Congo contemporain', 'Corruption', 'Dans quelle ville s’est tenue en juin 2018 la rencontre régionale de Transparency International durant laquelle l’estimation des 15 milliards USD a été réaffirmée ?', '["Kinshasa", "Goma", "Lubumbashi", "Kisangani"]'::jsonb, 0, 'La déclaration a été faite à Kinshasa lors d’une rencontre régionale Afrique de Transparency International.', 'https://www.radiookapi.net/node/182848', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1216', 'Congo contemporain', 'Handicap', 'Quelle estimation du nombre de Congolais vivant avec un handicap était citée par Le Monde en 2020 d’après la FENAPHACO ?', '["Environ 13 millions", "Environ 1 million", "Environ 3 millions", "Environ 30 millions"]'::jsonb, 0, 'Le Monde citait en 2020 une estimation de la FENAPHACO d’environ 13 millions de personnes.', 'https://www.lemonde.fr/afrique/article/2020/11/23/rdc-une-loi-en-discussion-pour-venir-en-aide-aux-13-millions-de-personnes-handicapees-du-pays_6060831_3212.html', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1217', 'Congo contemporain', 'Handicap', 'Quelle part de la population représentait l’estimation de 13 millions de personnes handicapées citée en 2020 ?', '["Environ 16 %", "Environ 2 %", "Environ 40 %", "Environ 60 %"]'::jsonb, 0, 'L’estimation citée équivalait à environ 16 % de la population de l’époque.', 'https://www.lemonde.fr/afrique/article/2020/11/23/rdc-une-loi-en-discussion-pour-venir-en-aide-aux-13-millions-de-personnes-handicapees-du-pays_6060831_3212.html', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1218', 'Congo contemporain', 'Handicap', 'En quelle année la RDC avait-elle ratifié la Convention de l’ONU relative aux droits des personnes handicapées selon l’article du Monde de 2020 ?', '["2015", "2006", "2020", "1997"]'::jsonb, 0, 'La RDC avait ratifié cette convention en 2015.', 'https://www.lemonde.fr/afrique/article/2020/11/23/rdc-une-loi-en-discussion-pour-venir-en-aide-aux-13-millions-de-personnes-handicapees-du-pays_6060831_3212.html', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1219', 'Économie & ressources', 'Agriculture', 'Combien d’hectares de terres arables la RDC possède-t-elle environ selon plusieurs études de développement ?', '["80 millions d’hectares", "8 millions d’hectares", "800 000 hectares", "200 millions d’hectares"]'::jsonb, 0, 'La Banque mondiale, l’AFD et d’autres travaux de référence citent environ 80 millions d’hectares de terres arables.', 'https://www.afd.fr/en/countries-regions/democratic-republic-congo', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1220', 'Économie & ressources', 'Agriculture', 'Quelle part environ des 80 millions d’hectares de terres arables congolaises est effectivement cultivée selon les estimations couramment citées ?', '["Environ 10 %", "Environ 50 %", "Environ 90 %", "100 %"]'::jsonb, 0, 'Les estimations citées indiquent qu’environ 10 % seulement sont cultivés.', 'https://futures.issafrica.org/geographic/countries/dr-congo/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1221', 'Économie & ressources', 'Agriculture', 'Quel potentiel théorique est parfois attribué à l’agriculture congolaise si ses terres étaient mieux valorisées ?', '["Pouvoir contribuer à nourrir environ un quart de la population mondiale", "Nourrir uniquement Kinshasa", "Remplacer toute l’agriculture mondiale", "Produire uniquement du café"]'::jsonb, 0, 'ISS African Futures décrit un potentiel agricole capable de nourrir environ un quart de la population mondiale ; il s’agit d’un potentiel théorique, non de la production actuelle.', 'https://futures.issafrica.org/geographic/countries/dr-congo/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1222', 'Économie & ressources', 'Agriculture', 'Le chiffre de 80 millions d’hectares signifie-t-il que toute cette surface est aujourd’hui cultivée ?', '["Non", "Oui", "Uniquement depuis 2025", "Seulement par les entreprises minières"]'::jsonb, 0, 'L’essentiel de ce potentiel reste sous-exploité.', 'https://www.afd.fr/en/countries-regions/democratic-republic-congo', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1224', 'Personnages', 'Patrice Lumumba', 'Qui écrit dans sa dernière lettre : « l’avenir du Congo est beau » ?', '["Patrice Lumumba", "Mobutu Sese Seko", "Joseph Kasa-Vubu", "Laurent-Désiré Kabila"]'::jsonb, 0, 'Cette formule est attribuée à Patrice Lumumba dans sa dernière lettre à Pauline Opango et à ses enfants.', 'https://upardc.org/lettre-de-lumumba/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1225', 'Personnages', 'Patrice Lumumba', 'Dans la dernière lettre de Lumumba, quelle mission dit-il attendre de ses enfants et de chaque Congolais ?', '["La reconstruction de l’indépendance et de la souveraineté du Congo", "Le retour à la colonisation", "La dissolution du Congo", "La suppression de l’indépendance"]'::jsonb, 0, 'Lumumba évoque la tâche de reconstruire l’indépendance et la souveraineté du Congo.', 'https://upardc.org/lettre-de-lumumba/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1226', 'Personnages', 'Patrice Lumumba', 'À qui Patrice Lumumba adresse-t-il la célèbre lettre dans laquelle il évoque « l’avenir du Congo » ?', '["À sa compagne Pauline et à travers elle à sa famille", "À Léopold II", "À Mobutu", "À Nelson Mandela"]'::jsonb, 0, 'Cette lettre est connue comme la dernière lettre de Lumumba à sa compagne Pauline Opango.', 'https://upardc.org/lettre-de-lumumba/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1227', 'Institutions & politique', 'Nationalité', 'La Constitution actuelle de la RDC autorise-t-elle en principe la double nationalité congolaise ?', '["Non", "Oui sans condition", "Oui uniquement avec la Belgique", "Oui uniquement après 50 ans"]'::jsonb, 0, 'L’article 10 affirme que la nationalité congolaise est une et exclusive et ne peut être détenue concurremment avec une autre.', 'https://mail.leganet.cd/Legislation/Constitution.htm', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1228', 'Institutions & politique', 'Nationalité', 'Quel article de la Constitution pose le principe de l’unicité et de l’exclusivité de la nationalité congolaise ?', '["Article 10", "Article 1", "Article 71", "Article 218"]'::jsonb, 0, 'Le principe figure à l’article 10.', 'https://mail.leganet.cd/Legislation/Constitution.htm', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1229', 'Institutions & politique', 'Nationalité', 'Selon la Constitution, la nationalité congolaise peut être :', '["D’origine ou d’acquisition individuelle", "Uniquement d’origine", "Uniquement accordée par le Président", "Uniquement provinciale"]'::jsonb, 0, 'L’article 10 distingue la nationalité d’origine et l’acquisition individuelle.', 'https://mail.leganet.cd/Legislation/Constitution.htm', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1230', 'Institutions & politique', 'Nationalité', 'Quelle formulation résume correctement la règle constitutionnelle actuelle sur la double nationalité ?', '["Le texte constitutionnel l’exclut en principe", "Elle est automatiquement reconnue à tous", "Elle dépend uniquement du gouverneur de province", "Elle n’est pas abordée par la Constitution"]'::jsonb, 0, 'La Constitution pose le principe d’une nationalité congolaise unique et exclusive.', 'https://mail.leganet.cd/Legislation/Constitution.htm', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1231', 'Institutions & politique', 'Constitution', 'Depuis sa promulgation en 2006, combien de révisions la Constitution congolaise a-t-elle connues jusqu’en septembre 2026 ?', '["Une seule", "Aucune", "Deux", "Cinq"]'::jsonb, 0, 'La Constitution de 2006 n’a été révisée qu’une fois, en 2011.', 'https://www.radiookapi.net/node/281140', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1232', 'Institutions & politique', 'Constitution', 'En quelle année la Constitution de 2006 a-t-elle été révisée ?', '["2011", "2008", "2016", "2021"]'::jsonb, 0, 'La révision a été opérée par la loi du 20 janvier 2011.', 'https://cassation.cd/textes-legaux/constitution-rdc', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1233', 'Institutions & politique', 'Constitution', 'Quel changement électoral majeur la révision constitutionnelle de 2011 a-t-elle apporté à l’élection présidentielle ?', '["Le passage de deux tours à un seul tour", "Le passage d’un à trois tours", "La suppression de l’élection présidentielle", "Le vote réservé au Sénat"]'::jsonb, 0, 'La révision de 2011 a notamment instauré l’élection présidentielle à un seul tour.', 'https://www.radiookapi.net/node/281140', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1234', 'Institutions & politique', 'Constitution', 'Combien d’articles la Présidence indique-t-elle avoir été modifiés par la loi de révision de 2011 ?', '["8 articles", "2 articles", "20 articles", "50 articles"]'::jsonb, 0, 'La Présidence cite les articles 71, 110, 126, 146, 197, 198, 218 et 226.', 'https://cassation.cd/textes-legaux/constitution-rdc', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1235', 'Congo contemporain', 'Kin-Bopeto', 'Que signifie l’expression « Kinshasa Bopeto » dans le nom du programme lancé en 2019 ?', '["Kinshasa propre", "Kinshasa numérique", "Kinshasa sportive", "Kinshasa minière"]'::jsonb, 0, 'Le programme est présenté comme une opération visant à rendre Kinshasa propre et salubre.', 'https://www.radiookapi.net/2019/10/20/actualite/politique/felix-tshisekedi-lance-loperation-kinshasa-bopeto-bandalungwa', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1236', 'Congo contemporain', 'Kin-Bopeto', 'À quelle date Félix Tshisekedi lance-t-il officiellement l’opération Kinshasa Bopeto ?', '["19 octobre 2019", "19 octobre 2018", "30 juin 2020", "1er janvier 2019"]'::jsonb, 0, 'Le lancement officiel a lieu le 19 octobre 2019 à Bandalungwa.', 'https://www.radiookapi.net/2019/10/20/actualite/politique/felix-tshisekedi-lance-loperation-kinshasa-bopeto-bandalungwa', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1237', 'Congo contemporain', 'Kin-Bopeto', 'Quel gouverneur de Kinshasa avait initié le programme Kin-Bopeto ?', '["Gentiny Ngobila", "André Kimbuta", "Daniel Bumba", "Jean Ngoy"]'::jsonb, 0, 'Le programme a été initié par le gouverneur Gentiny Ngobila.', 'https://www.radiookapi.net/2019/10/20/actualite/politique/felix-tshisekedi-lance-loperation-kinshasa-bopeto-bandalungwa', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1238', 'Congo contemporain', 'Kin-Bopeto', 'Quel était l’objectif principal de Kin-Bopeto ?', '["L’assainissement et la lutte contre l’insalubrité à Kinshasa", "Construire des mines", "Créer une nouvelle monnaie", "Organiser la CAN"]'::jsonb, 0, 'Le programme visait principalement la salubrité, la gestion des déchets et le changement des comportements.', 'https://www.radiookapi.net/2019/10/20/actualite/politique/felix-tshisekedi-lance-loperation-kinshasa-bopeto-bandalungwa', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1239', 'Congo contemporain', 'État civil', 'Quelle proportion d’enfants de moins de 5 ans était enregistrée à l’état civil en RDC selon l’UNICEF dans les données citées en 2022 ?', '["Environ 40 %", "Environ 10 %", "Environ 75 %", "Environ 100 %"]'::jsonb, 0, 'L’UNICEF indique qu’environ 40 % des enfants de moins de 5 ans sont enregistrés à l’état civil.', 'https://www.unicef.org/drcongo/communiques-presse/lancement-projet-digitalisation-registre-vaccination', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1240', 'Congo contemporain', 'État civil', 'Selon l’UNICEF, quelle proportion environ des enfants de moins de 5 ans disposait effectivement d’un acte de naissance dans les données publiées ?', '["13 %", "40 %", "80 %", "95 %"]'::jsonb, 0, 'La page UNICEF sur la protection de l’enfance indique que 13 % disposent d’un acte de naissance.', 'https://www.unicef.org/drcongo/en/what-we-do/child-protection', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1241', 'Congo contemporain', 'État civil', 'Quel projet lancé en RDC vise à relier l’enregistrement des naissances et le registre de vaccination ?', '["La digitalisation du registre de vaccination incluant l’enregistrement à l’état civil", "Kin-Bopeto", "Likofi", "Grand Inga"]'::jsonb, 0, 'L’objectif est d’utiliser la digitalisation des services de santé pour améliorer aussi l’enregistrement des naissances.', 'https://www.unicef.org/drcongo/communiques-presse/lancement-projet-digitalisation-registre-vaccination', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1242', 'Congo contemporain', 'État civil', 'Pourquoi l’absence d’enregistrement à l’état civil est-elle un problème majeur pour un enfant ?', '["Elle peut priver l’enfant d’une identité juridique et compliquer l’accès à des droits et services", "Elle empêche uniquement de jouer au football", "Elle change sa province de naissance", "Elle supprime automatiquement sa nationalité"]'::jsonb, 0, 'L’enregistrement des naissances constitue la base de l’identité juridique et facilite l’accès aux droits et services.', 'https://www.unicef.org/drcongo/en/what-we-do/child-protection', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1243', 'Congo contemporain', 'Passeports', 'Combien coûtait le passeport biométrique congolais dans le contrat dénoncé par une enquête Reuters en 2017 ?', '["185 USD", "50 USD", "75 USD", "300 USD"]'::jsonb, 0, 'L’enquête Reuters de 2017 indiquait un prix de 185 USD pour le passeport biométrique.', 'https://www.africanews.com/2017/04/18/dr-congo-opposition-wants-probe-into-expensive-passports/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1244', 'Congo contemporain', 'Passeports', 'Selon les documents consultés par Reuters en 2017, quelle part des 185 USD revenait au gouvernement congolais ?', '["65 USD", "185 USD", "120 USD", "10 USD"]'::jsonb, 0, 'Reuters indiquait que 65 USD revenaient à l’État dans la structure financière examinée.', 'https://www.africanews.com/2017/04/18/dr-congo-opposition-wants-probe-into-expensive-passports/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1245', 'Congo contemporain', 'Passeports', 'Selon l’enquête Reuters de 2017, combien de dollars par passeport devaient aller à la société LRPS ?', '["60 USD", "5 USD", "100 USD", "185 USD"]'::jsonb, 0, 'Reuters indiquait un versement de 60 USD par passeport à LRPS.', 'https://www.africanews.com/2017/04/18/dr-congo-opposition-wants-probe-into-expensive-passports/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1246', 'Congo contemporain', 'Passeports', 'Quelle évolution judiciaire intervient en Belgique en septembre 2026 dans l’affaire liée au contrat de passeports congolais ?', '["Une juridiction ordonne le renvoi de Semlex et d’autres prévenus devant un tribunal", "Tous les prévenus sont définitivement condamnés", "L’affaire est classée définitivement", "La RDC supprime les passeports"]'::jsonb, 0, 'Reuters rapporte qu’une juridiction bruxelloise a ordonné un procès ; cela ne constitue pas encore une déclaration de culpabilité.', 'https://www.reuters.com/world/belgian-court-orders-trial-corruption-money-laundering-linked-congo-passport-2026-09-01/', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1247', 'Congo contemporain', 'Passeports', 'Comment faut-il présenter juridiquement les accusations dans l’affaire des passeports en 2026 ?', '["Comme des allégations faisant l’objet d’une procédure, sans présumer la culpabilité", "Comme une condamnation définitive de toutes les personnes citées", "Comme une rumeur sans enquête", "Comme une décision de la Cour pénale internationale"]'::jsonb, 0, 'Le renvoi devant un tribunal ouvre une phase de jugement ; la culpabilité ne doit pas être présumée.', 'https://www.reuters.com/world/belgian-court-orders-trial-corruption-money-laundering-linked-congo-passport-2026-09-01/', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1248', 'Congo contemporain', 'Justice - 100 jours', 'À quel programme gouvernemental était liée l’affaire judiciaire dite des « 100 jours » concernant Vital Kamerhe ?', '["Au programme d’urgence des 100 jours du président Félix Tshisekedi", "À Kin-Bopeto", "À l’Opération Likofi", "À Grand Inga"]'::jsonb, 0, 'L’affaire concernait notamment des fonds liés aux maisons préfabriquées du programme d’urgence des 100 jours.', 'https://www.radiookapi.net/2022/06/23/actualite/justice/proces-100-jours-vital-kamerhe-acquitte', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1249', 'Congo contemporain', 'Justice - 100 jours', 'Quelle peine Vital Kamerhe avait-il reçue en première instance en 2020 dans l’affaire des 100 jours ?', '["20 ans de travaux forcés", "5 ans", "10 ans", "Acquittement immédiat"]'::jsonb, 0, 'Il avait été condamné à 20 ans en première instance en 2020.', 'https://www.radiookapi.net/2022/06/23/actualite/justice/proces-100-jours-vital-kamerhe-acquitte', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1250', 'Congo contemporain', 'Justice - 100 jours', 'À combien la peine de Vital Kamerhe avait-elle été réduite en appel avant l’intervention de la Cour de cassation ?', '["13 ans", "2 ans", "7 ans", "25 ans"]'::jsonb, 0, 'La peine avait été ramenée à 13 ans en appel.', 'https://www.radiookapi.net/2022/04/11/actualite/justice/proces-de-100-jours-la-cour-de-cassation-casse-larret-de-la-cour-dappel', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1251', 'Congo contemporain', 'Justice - 100 jours', 'Que décide la Cour de cassation en avril 2022 dans l’affaire Kamerhe ?', '["Elle casse l’arrêt d’appel pour vices de procédure et renvoie l’affaire devant une autre composition", "Elle le condamne définitivement à vie", "Elle classe l’affaire sans nouveau procès", "Elle saisit la Cour pénale internationale"]'::jsonb, 0, 'La Cour de cassation a cassé l’arrêt et renvoyé l’affaire pour être rejugée.', 'https://www.radiookapi.net/2022/04/11/actualite/justice/proces-de-100-jours-la-cour-de-cassation-casse-larret-de-la-cour-dappel', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1252', 'Congo contemporain', 'Justice - 100 jours', 'Quelle décision la Cour d’appel de Kinshasa-Gombe rend-elle le 23 juin 2022 concernant Vital Kamerhe ?', '["Elle l’acquitte", "Elle confirme 20 ans", "Elle le condamne à 5 ans", "Elle reporte le procès à 2030"]'::jsonb, 0, 'Vital Kamerhe a été acquitté le 23 juin 2022 ; les infractions n’ont pas été retenues par la cour.', 'https://www.radiookapi.net/2022/06/23/actualite/justice/proces-100-jours-vital-kamerhe-acquitte', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1253', 'Congo contemporain', 'Économie positive', 'Quel taux de croissance économique la Banque mondiale retient-elle finalement pour la RDC en 2021 ?', '["6,2 %", "1,7 %", "12 %", "-6,2 %"]'::jsonb, 0, 'La croissance de 2021, initialement estimée à 5,7 %, a été révisée à 6,2 %.', 'https://www.worldbank.org/en/news/press-release/2022/10/07/democratic-republic-of-congo-economic-update', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1254', 'Congo contemporain', 'Économie positive', 'Après quel ralentissement de croissance en 2020 l’économie congolaise rebondit-elle à 6,2 % en 2021 ?', '["1,7 %", "10 %", "5 %", "-10 %"]'::jsonb, 0, 'La Banque mondiale indique un ralentissement à 1,7 % en 2020, suivi d’un fort rebond en 2021.', 'https://www.worldbank.org/en/news/press-release/2022/10/07/democratic-republic-of-congo-economic-update', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1255', 'Congo contemporain', 'Développement humain', 'Quelle valeur de l’Indice de développement humain (IDH) le PNUD attribue-t-il à la RDC pour 2023 dans son rapport 2025 ?', '["0,522", "0,900", "0,300", "0,750"]'::jsonb, 0, 'Le Rapport sur le développement humain 2025 donne une valeur d’IDH de 0,522 pour 2023.', 'https://hdr.undp.org/sites/default/files/2025_HDR/HDR25_Statistical_Annex_Tables_1-7.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1256', 'Congo contemporain', 'Développement humain', 'Quel rang la RDC occupe-t-elle dans le classement IDH 2023 publié dans le Rapport sur le développement humain 2025 ?', '["171e", "71e", "101e", "191e"]'::jsonb, 0, 'Le PNUD classe la RDC 171e pour les données 2023.', 'https://hdr.undp.org/sites/default/files/2025_HDR/HDR25_Statistical_Annex_Tables_1-7.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1257', 'Géographie & 26 provinces', 'Frontières', 'Combien de pays ont une frontière avec la RDC ?', '["9", "6", "7", "12"]'::jsonb, 0, 'La RDC partage une frontière avec neuf pays.', 'https://www.cia.gov/static/b2fcc8d80f910b0c91f4a74d33b5c7e6/DRC_Administrative.pdf', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1258', 'Géographie & 26 provinces', 'Frontières', 'Lequel de ces pays n’est PAS frontalier de la RDC ?', '["Kenya", "Rwanda", "Zambie", "Soudan du Sud"]'::jsonb, 0, 'Le Kenya n’a pas de frontière avec la RDC.', 'https://www.cia.gov/static/b2fcc8d80f910b0c91f4a74d33b5c7e6/DRC_Administrative.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1259', 'Géographie & 26 provinces', 'Frontières', 'Quelle liste contient uniquement des pays frontaliers de la RDC ?', '["Angola, Zambie, Tanzanie et Ouganda", "Kenya, Cameroun, Malawi et Gabon", "Éthiopie, Kenya, Congo et Malawi", "Mozambique, Angola, Kenya et Tchad"]'::jsonb, 0, 'Parmi les neuf voisins figurent notamment Angola, Zambie, Tanzanie et Ouganda.', 'https://www.cia.gov/static/b2fcc8d80f910b0c91f4a74d33b5c7e6/DRC_Administrative.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1260', 'Histoire', 'Mobutu et Authenticité', 'Quel président est associé à la politique du « recours à l’authenticité » au Zaïre ?', '["Mobutu Sese Seko", "Patrice Lumumba", "Laurent-Désiré Kabila", "Joseph Kasa-Vubu"]'::jsonb, 0, 'Mobutu fait du recours à l’authenticité un axe central de son régime.', 'https://www.elysee.fr/valery-giscard-d-estaing/1975/08/07/allocution-de-m-valery-giscard-destaing-au-stade-du-20-mai-kinshasa-7-aout-1975', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1261', 'Histoire', 'Mobutu et Authenticité', 'À quelle date le discours de Mobutu proclamant le « recours à l’authenticité » est-il associé dans les archives de l’Élysée ?', '["30 décembre 1971", "30 juin 1960", "24 novembre 1965", "17 mai 1997"]'::jsonb, 0, 'Les archives de l’Élysée renvoient au discours de Mobutu du 30 décembre 1971.', 'https://www.elysee.fr/valery-giscard-d-estaing/1975/08/07/allocution-de-m-valery-giscard-destaing-au-stade-du-20-mai-kinshasa-7-aout-1975', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1262', 'Histoire', 'Mobutu et Authenticité', 'Quelle transformation sociale accompagne notamment la politique d’authenticité ?', '["Le changement de noms de lieux et de personnes vers des appellations africaines", "L’adoption du dollar américain comme unique monnaie", "La suppression de toutes les langues nationales", "Le retour de Léopoldville comme capitale"]'::jsonb, 0, 'Les travaux académiques sur l’authenticité montrent son impact sur les noms de personnes, de lieux et d’institutions.', 'https://www.persee.fr/doc/mots_0243-6450_1983_num_6_1_1095', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1263', 'Histoire', 'Mobutu et Authenticité', 'Quel objectif idéologique Mobutu associe au « recours à l’authenticité » ?', '["Rechercher et valoriser des références culturelles africaines propres au pays", "Restaurer l’administration coloniale", "Interdire toute culture congolaise", "Créer une monarchie belge"]'::jsonb, 0, 'Le discours de l’authenticité vise à rompre avec certaines références coloniales et à valoriser des références culturelles africaines.', 'https://www.persee.fr/doc/mots_0243-6450_1983_num_6_1_1095', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1264', 'Institutions & politique', 'Peine de mort', 'La peine de mort existe-t-elle encore dans le droit congolais en 2026 ?', '["Oui", "Non, elle est abolie", "Seulement en droit coutumier", "Uniquement en province"]'::jsonb, 0, 'La RDC demeure un État non abolitionniste : son droit pénal prévoit encore la peine capitale.', 'https://worldcoalition.org/fr/pays/republique-democratique-du-congo/', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1265', 'Institutions & politique', 'Peine de mort', 'Quel texte ancien prévoit notamment la peine de mort parmi les peines applicables en RDC ?', '["Le Code pénal de 1940", "La Constitution de 2006 uniquement", "Le Code du numérique", "La loi électorale"]'::jsonb, 0, 'Le Code pénal congolais de 1940 prévoit la peine de mort parmi les peines applicables.', 'https://worldcoalition.org/fr/pays/republique-democratique-du-congo/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1266', 'Institutions & politique', 'Peine de mort', 'Depuis quelle année un moratoire de fait sur les exécutions était-il observé en RDC avant sa levée ?', '["2003", "1990", "2006", "2011"]'::jsonb, 0, 'Un moratoire de fait sur les exécutions était observé depuis 2003.', 'https://www.eeas.europa.eu/eeas/rdc-d%C3%A9claration-du-porte-parole-sur-le-r%C3%A9tablissement-de-la-peine-de-mort_und_en', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1267', 'Institutions & politique', 'Peine de mort', 'En quelle année le gouvernement congolais a-t-il levé le moratoire sur l’exécution de la peine de mort ?', '["2024", "2018", "2020", "2026"]'::jsonb, 0, 'La décision de lever le moratoire a été formalisée en mars 2024.', 'https://www.peinedemort.org/document/12106/Note-Circulaire-relative-a-la-levee-du-moratoire-sur-l-execution-de-la-peine-de-mort-en-Republique-democratique-du-Congo', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1268', 'Institutions & politique', 'Peine de mort', 'À quelle date la note circulaire levant le moratoire sur les exécutions a-t-elle été signée ?', '["13 mars 2024", "13 mars 2003", "30 juin 2024", "9 février 2023"]'::jsonb, 0, 'La note circulaire n°002 est datée du 13 mars 2024.', 'https://www.peinedemort.org/document/12106/Note-Circulaire-relative-a-la-levee-du-moratoire-sur-l-execution-de-la-peine-de-mort-en-Republique-democratique-du-Congo', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1269', 'Institutions & politique', 'Peine de mort', 'Quelle ministre de la Justice a signé en mars 2024 la note circulaire levant le moratoire ?', '["Rose Mutombo Kiese", "Judith Suminwa Tuluka", "Ève Bazaiba", "Thérèse Kayikwamba Wagner"]'::jsonb, 0, 'La note a été signée par Rose Mutombo Kiese, alors ministre de la Justice et garde des Sceaux.', 'https://www.peinedemort.org/document/12106/Note-Circulaire-relative-a-la-levee-du-moratoire-sur-l-execution-de-la-peine-de-mort-en-Republique-democratique-du-Congo', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1270', 'Institutions & politique', 'Peine de mort', 'Dans quel contexte la note de mars 2024 prévoit-elle notamment l’exécution possible d’une condamnation à mort irrévocable ?', '["Temps de guerre, état de siège ou d’urgence, opérations de maintien de l’ordre ou circonstances exceptionnelles", "Uniquement pour les infractions routières", "Uniquement pour les dettes civiles", "Uniquement en période électorale"]'::jsonb, 0, 'La note vise des condamnations irrévocables intervenues dans des circonstances exceptionnelles définies par le texte.', 'https://www.peinedemort.org/document/12106/Note-Circulaire-relative-a-la-levee-du-moratoire-sur-l-execution-de-la-peine-de-mort-en-Republique-democratique-du-Congo', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1271', 'Institutions & politique', 'Peine de mort', 'Parmi ces infractions, laquelle est expressément citée dans la note de 2024 comme pouvant relever de la peine capitale ?', '["La trahison", "Le stationnement interdit", "Le retard fiscal simple", "La diffamation civile"]'::jsonb, 0, 'La note cite notamment la trahison, l’espionnage, certaines bandes armées et mouvements insurrectionnels.', 'https://www.peinedemort.org/document/12106/Note-Circulaire-relative-a-la-levee-du-moratoire-sur-l-execution-de-la-peine-de-mort-en-Republique-democratique-du-Congo', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1272', 'Institutions & politique', 'Peine de mort', 'Quelle est l’année de la dernière exécution connue en RDC selon les organisations spécialisées ?', '["2003", "2010", "2024", "2025"]'::jsonb, 0, 'Aucune exécution n’est recensée depuis 2003.', 'https://worldcoalition.org/fr/pays/republique-democratique-du-congo/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1273', 'Institutions & politique', 'Peine de mort', 'Des exécutions ont-elles été recensées en RDC en 2024 et 2025 par les organisations de suivi citées ?', '["Non", "Oui, plus de 100", "Oui, exactement 10", "Oui, uniquement à Kinshasa"]'::jsonb, 0, 'Les bases de suivi indiquent zéro exécution recensée en 2024 et en 2025, malgré la levée du moratoire.', 'https://worldcoalition.org/fr/pays/republique-democratique-du-congo/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1274', 'Institutions & politique', 'Peine de mort', 'Combien de condamnations à mort Amnesty International disait-elle avoir recensées devant des juridictions militaires après mars 2024, dans son point de janvier 2025 ?', '["Au moins 300", "30", "3 000", "50"]'::jsonb, 0, 'Amnesty International indiquait au moins 300 condamnations à mort prononcées par des tribunaux militaires depuis l’annonce de mars 2024.', 'https://www.amnesty.org/fr/documents/afr62/8938/2025/fr/', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1275', 'Institutions & politique', 'Peine de mort', 'Combien de condamnations à mort Amnesty International a-t-elle recensées en RDC pour l’année 2025 ?', '["Au moins 359", "59", "125", "1 359"]'::jsonb, 0, 'Dans son bilan 2025, Amnesty International recense au moins 359 condamnations à mort en RDC.', 'https://www.amnesty.org/fr/latest/news/2026/05/death-penalty-in-2025-facts-and-figures/', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1276', 'Institutions & politique', 'Peine de mort', 'Quelle distinction est essentielle pour comprendre la situation de la peine de mort en RDC ?', '["Une condamnation à mort peut être prononcée sans qu’une exécution ait effectivement lieu", "Toute condamnation entraîne automatiquement une exécution le jour même", "La peine n’existe que dans les médias", "La peine est uniquement symbolique et non prévue par le droit"]'::jsonb, 0, 'La RDC continue de prononcer des condamnations à mort ; cela doit être distingué des exécutions effectives, dont aucune n’est recensée depuis 2003.', 'https://worldcoalition.org/fr/pays/republique-democratique-du-congo/', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1277', 'Congo contemporain', 'Diaspora - Combattants', 'Dans le contexte de la diaspora congolaise en Europe, qui appelle-t-on couramment les « combattants » ?', '["Un ensemble diffus de militants politiques de la diaspora, historiquement très opposés au régime de Joseph Kabila", "Une unité officielle des FARDC", "Une équipe nationale de football", "Une association unique créée par l’État"]'::jsonb, 0, 'Les travaux académiques décrivent les combattants comme un phénomène militant diffus de la diaspora, et non comme une seule organisation hiérarchisée.', 'https://academic.oup.com/jrs/article/33/4/727/5851540', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1278', 'Congo contemporain', 'Diaspora - Combattants', 'Le mouvement des « combattants » de la diaspora est-il une organisation unique et centralisée ?', '["Non", "Oui, avec un président élu unique", "Oui, c’est une branche de l’armée", "Oui, c’est un parti enregistré en RDC"]'::jsonb, 0, 'Le terme recouvre différents réseaux et groupes militants ; il ne désigne pas une organisation unique.', 'https://academic.oup.com/jrs/article/33/4/727/5851540', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1279', 'Congo contemporain', 'Diaspora - Combattants', 'À quelle période les « combattants » deviennent-ils un phénomène politique important dans la diaspora congolaise ?', '["Dans les années 2000", "Dans les années 1940", "Uniquement après 2025", "Au XIXe siècle"]'::jsonb, 0, 'Les travaux universitaires situent leur émergence comme phénomène diasporique dans les années 2000.', 'https://academic.oup.com/jrs/article/33/4/727/5851540', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1280', 'Congo contemporain', 'Diaspora - Combattants', 'Quel incident de 2006 à Londres est devenu emblématique de l’action des « combattants » ?', '["L’agression du responsable politique She Okitundu", "L’incendie du Parlement britannique", "La fermeture de l’ONU", "L’arrestation de Nelson Mandela"]'::jsonb, 0, 'Une étude universitaire cite l’agression de She Okitundu à Londres en 2006 comme un épisode emblématique.', 'https://academic.oup.com/jrs/article/33/4/727/5851540', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1281', 'Congo contemporain', 'Diaspora - Combattants', 'Pourquoi certains « combattants » ont-ils cherché à empêcher des concerts de musiciens congolais en Europe ?', '["Ils accusaient certains artistes d’être proches ou de faire la promotion du pouvoir de Kinshasa", "Ils voulaient interdire toute musique congolaise", "Ils réclamaient uniquement des billets gratuits", "Ils s’opposaient à la rumba pour des raisons linguistiques"]'::jsonb, 0, 'Leur opposition visait notamment des artistes perçus comme soutiens du régime de Joseph Kabila.', 'https://www.lemonde.fr/afrique/article/2023/07/02/fally-ipupa-pas-de-danse-risque-entre-paris-et-kinshasa_6180209_3212.html', null, null, 2, 'valide') on conflict (id) do nothing;
