insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1401', 'Congo contemporain', 'Justice - Joseph Kabila', 'La condamnation à mort de Joseph Kabila en 2025 a été prononcée dans quelles conditions ?', '["À la suite d’un référendum", "Après un procès civil en Belgique", "Par contumace", "Après sa présence au procès"]'::jsonb, 2, 'Reuters indique que Joseph Kabila n’était pas présent au procès et a été condamné par contumace.', 'https://www.reuters.com/world/africa/congo-military-court-sentences-ex-president-kabila-death-absentia-2025-09-30/', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1402', 'Congo contemporain', 'Justice - Joseph Kabila', 'Parmi les infractions retenues contre Joseph Kabila lors de sa condamnation de 2025 figurait laquelle ?', '["La contrefaçon monétaire", "La corruption sportive", "La trahison", "La fraude fiscale en Belgique"]'::jsonb, 2, 'La juridiction militaire l’a notamment reconnu coupable de trahison, de crimes de guerre et de crimes contre l’humanité.', 'https://www.reuters.com/world/africa/congo-military-court-sentences-ex-president-kabila-death-absentia-2025-09-30/', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1403', 'Congo contemporain', 'Justice - Joseph Kabila', 'Quelle position Joseph Kabila a-t-il publiquement défendue face aux poursuites ayant conduit à sa condamnation de 2025 ?', '["Il a plaidé coupable", "Il a demandé une grâce présidentielle", "Il a reconnu diriger le M23", "Il a nié les accusations et dénoncé un procès politique"]'::jsonb, 3, 'L’ancien président a nié les faits qui lui étaient reprochés et présenté la procédure comme politiquement motivée.', 'https://www.reuters.com/world/africa/congo-military-court-sentences-ex-president-kabila-death-absentia-2025-09-30/', null, null, 5, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1404', 'Congo contemporain', 'Corneille Nangaa et AFC', 'Quelle institution Corneille Nangaa a-t-il dirigée avant de devenir chef de l’Alliance Fleuve Congo ?', '["La Banque centrale", "La MONUSCO", "La CENI", "La Cour constitutionnelle"]'::jsonb, 2, 'Corneille Nangaa a dirigé la Commission électorale nationale indépendante et supervisé les élections de 2018.', 'https://www.reuters.com/world/africa/congos-ex-election-chief-turned-rebel-boss-builds-insurgency-2025-01-27/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1405', 'Congo contemporain', 'Corneille Nangaa et AFC', 'Quel mouvement Corneille Nangaa dirige-t-il dans le contexte du conflit dans l’Est ?', '["MLC", "AFDL", "Alliance Fleuve Congo (AFC)", "CNDP"]'::jsonb, 2, 'Corneille Nangaa est le dirigeant de l’Alliance Fleuve Congo, une coalition politico-militaire.', 'https://www.reuters.com/world/africa/congos-ex-election-chief-turned-rebel-boss-builds-insurgency-2025-01-27/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1406', 'Congo contemporain', 'Corneille Nangaa et AFC', 'Quel groupe armé constitue le principal partenaire militaire de l’AFC de Corneille Nangaa ?', '["Les FDLR", "Le M23", "Les ADF", "La LRA"]'::jsonb, 1, 'Reuters décrit l’AFC comme une coalition incluant le M23, qui en constitue la principale force armée.', 'https://www.reuters.com/world/africa/congos-ex-election-chief-turned-rebel-boss-builds-insurgency-2025-01-27/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1407', 'Congo contemporain', 'Corneille Nangaa et AFC', 'Quelle fonction Corneille Nangaa exerçait-il lors de l’élection présidentielle congolaise de 2018 ?', '["Président de la CENI", "Président du Sénat", "Premier ministre", "Chef d’état-major"]'::jsonb, 0, 'Il était président de la CENI au moment du scrutin de 2018.', 'https://www.reuters.com/world/africa/congos-ex-election-chief-turned-rebel-boss-builds-insurgency-2025-01-27/', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1408', 'Congo contemporain', 'Corneille Nangaa et AFC', 'De quelle province est originaire Corneille Nangaa selon son profil rapporté par Reuters ?', '["Lualaba", "Kongo Central", "Kwilu", "Haut-Uele"]'::jsonb, 3, 'Reuters indique qu’il est originaire du Haut-Uele, dans le nord-est de la RDC.', 'https://www.reuters.com/world/africa/congos-ex-election-chief-turned-rebel-boss-builds-insurgency-2025-01-27/', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1409', 'Histoire', 'M23 - Origine du nom', 'Pourquoi le mouvement rebelle M23 porte-t-il ce nom ?', '["Parce qu’il a été créé par 23 officiers", "En référence à l’accord du 23 mars 2009", "En référence au 23e bataillon", "En référence au 23 mars 2012"]'::jsonb, 1, 'Le nom renvoie à l’accord politique du 23 mars 2009 entre le gouvernement congolais et le CNDP.', 'https://digitallibrary.un.org/record/729498/files/S_2012_348-FR.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1410', 'Histoire', 'M23 - Origine du nom', 'Avec quel mouvement le gouvernement congolais avait-il signé l’accord du 23 mars 2009 auquel se réfère le M23 ?', '["Le CNDP", "L’AFDL", "L’UDPS", "Le MLC"]'::jsonb, 0, 'L’accord du 23 mars 2009 concernait notamment le Congrès national pour la défense du peuple, le CNDP.', 'https://digitallibrary.un.org/record/729498/files/S_2012_348-FR.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1411', 'Histoire', 'M23 - Origine du nom', 'En quelle année le Mouvement du 23 mars a-t-il été créé ?', '["2012", "2014", "2010", "2009"]'::jsonb, 0, 'Le communiqué de création du M23 est daté du 6 mai 2012.', 'https://digitallibrary.un.org/record/729498/files/S_2012_348-FR.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1412', 'Histoire', 'M23 - Origine du nom', 'Quel officier est désigné coordonnateur du M23 dans le communiqué de création du 6 mai 2012 ?', '["Sultani Makenga", "Laurent Nkunda", "Jean-Pierre Bemba", "James Kabarebe"]'::jsonb, 0, 'Le communiqué du 6 mai 2012 désigne le colonel Sultani Makenga comme coordonnateur du Mouvement du 23 mars.', 'https://digitallibrary.un.org/record/729498/files/S_2012_348-FR.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1413', 'Histoire', 'Rapport Mapping', 'Quelle institution des Nations unies a conduit le Projet Mapping sur la RDC ?', '["Le Haut-Commissariat des Nations unies aux droits de l’homme", "L’OMS", "La FAO", "L’UNESCO"]'::jsonb, 0, 'Le Projet Mapping a été conduit par le Haut-Commissariat des Nations unies aux droits de l’homme.', 'https://monusco.unmissions.org/fr/news/rdc-projet-mapping-concernant-les-violations-des-droits-de-lhomme-1993-2003', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1414', 'Histoire', 'Rapport Mapping', 'Quelle période historique couvre le rapport Mapping de l’ONU sur la RDC ?', '["1960 à 1965", "Mars 1993 à juin 2003", "1971 à 1990", "2006 à 2018"]'::jsonb, 1, 'Le rapport documente les violations les plus graves commises entre mars 1993 et juin 2003.', 'https://monusco.unmissions.org/fr/news/rdc-projet-mapping-concernant-les-violations-des-droits-de-lhomme-1993-2003', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1415', 'Histoire', 'Rapport Mapping', 'Combien d’incidents violents présumés le rapport Mapping décrit-il ?', '["617", "417", "1 617", "217"]'::jsonb, 0, 'Le rapport décrit 617 incidents violents présumés répondant au seuil de gravité retenu.', 'https://monusco.unmissions.org/fr/news/rdc-projet-mapping-concernant-les-violations-des-droits-de-lhomme-1993-2003', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1416', 'Histoire', 'Rapport Mapping', 'En quelle année le rapport Mapping sur la RDC a-t-il été publié ?', '["2006", "2010", "2003", "2015"]'::jsonb, 1, 'Le rapport a été publié en août 2010.', 'https://monusco.unmissions.org/fr/news/rdc-projet-mapping-concernant-les-violations-des-droits-de-lhomme-1993-2003', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1417', 'Histoire', 'Rapport Mapping', 'Environ combien de témoins les équipes Mapping ont-elles rencontrés ?', '["Moins de 300", "Plus de 1 280", "Plus de 10 000", "Environ 120"]'::jsonb, 1, 'Les équipes de terrain ont rencontré plus de 1 280 témoins pour corroborer ou infirmer les informations.', 'https://monusco.unmissions.org/fr/news/rdc-projet-mapping-concernant-les-violations-des-droits-de-lhomme-1993-2003', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1418', 'Histoire', 'Rapport Mapping', 'Quelle est la nature juridique du rapport Mapping ?', '["Un traité de paix", "Un exercice de documentation préliminaire, pas un jugement pénal", "Une constitution provisoire", "Une condamnation définitive de tous les acteurs cités"]'::jsonb, 1, 'Le Mapping inventorie des violations présumées et peut orienter des mécanismes de justice ; il ne remplace pas une décision judiciaire.', 'https://monusco.unmissions.org/fr/news/rdc-projet-mapping-concernant-les-violations-des-droits-de-lhomme-1993-2003', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1419', 'Histoire', 'Guerres du Congo - mortalité', 'Combien de décès excédentaires l’IRC estimait-il entre août 1998 et avril 2007 en RDC ?', '["Environ 1,4 million", "Environ 5,4 millions", "Environ 12 millions", "Environ 540 000"]'::jsonb, 1, 'L’International Rescue Committee estimait à environ 5,4 millions les décès excédentaires associés à la guerre et à ses conséquences sur cette période.', 'https://www.rescue.org/report/mortality-democratic-republic-congo-ongoing-crisis', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1420', 'Histoire', 'Guerres du Congo - mortalité', 'L’estimation de 5,4 millions de morts liée aux guerres du Congo correspond-elle uniquement à des personnes tuées au combat ?', '["Oui, uniquement des soldats", "Non", "Oui, uniquement des victimes de bombardements", "Oui, uniquement des civils exécutés"]'::jsonb, 1, 'Il s’agit d’une estimation de mortalité excédentaire : une grande partie des décès résulte des maladies, de la faim et de l’effondrement des services de santé.', 'https://www.rescue.org/report/mortality-democratic-republic-congo-ongoing-crisis', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1421', 'Histoire', 'Guerres du Congo - mortalité', 'Selon l’IRC, environ combien de décès excédentaires avaient encore eu lieu après la fin formelle de la guerre en 2002, jusqu’en 2007 ?', '["Environ 500 000", "Environ 2,1 millions", "Environ 210 000", "Environ 8 millions"]'::jsonb, 1, 'L’IRC estimait qu’environ 2,1 millions de décès excédentaires étaient survenus après la fin formelle de la guerre en 2002.', 'https://www.rescue.org/report/mortality-democratic-republic-congo-ongoing-crisis', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1422', 'Congo contemporain', 'Santé - paludisme', 'Selon l’OMS, environ combien de cas de paludisme étaient estimés en RDC en 2022 ?', '["Environ 75 millions", "Environ 30,7 millions", "Environ 3 millions", "Environ 8 millions"]'::jsonb, 1, 'Le World Malaria Report 2023 estimait environ 30,65 millions de cas de paludisme en RDC en 2022.', 'https://www.afro.who.int/sites/default/files/2023-12/9789240086173-eng.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1423', 'Congo contemporain', 'Santé - paludisme', 'La RDC faisait-elle partie des pays supportant la plus lourde charge mondiale de paludisme au début des années 2020 ?', '["Oui", "Seulement chez les voyageurs", "Uniquement dans une seule province", "Non, le paludisme y est presque éliminé"]'::jsonb, 0, 'La RDC figure parmi les pays les plus touchés au monde par le paludisme.', 'https://www.afro.who.int/sites/default/files/2023-12/9789240086173-eng.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1424', 'Congo contemporain', 'Santé - paludisme', 'En 2024, quelle part approximative des décès dus au paludisme dans la région africaine de l’OMS était attribuée à la RDC ?', '["1,7 %", "4 %", "11,7 %", "31,9 %"]'::jsonb, 2, 'L’OMS indique que la RDC représentait environ 11,7 % des décès liés au paludisme dans la région africaine en 2024.', 'https://www.who.int/news-room/fact-sheets/detail/malaria', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1425', 'Congo contemporain', 'Santé - typhoïde', 'Dans une étude de surveillance publiée en 2024, quel pays présentait l’incidence de fièvre typhoïde la plus élevée parmi les sites étudiés ?', '["La RDC", "Le Sénégal", "Le Ghana", "Le Kenya"]'::jsonb, 0, 'L’étude multicentrique citée par l’International Vaccine Institute relevait l’incidence la plus élevée dans les sites de RDC.', 'https://www.ivi.int/major-typhoid-fever-surveillance-study-in-sub-saharan-africa-indicates-need-for-the-introduction-of-typhoid-conjugate-vaccines-in-endemic-countries/', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1426', 'Congo contemporain', 'Éducation - bourses', 'Quelle structure interministérielle coordonne la gestion de nombreuses bourses d’études à l’étranger pour la RDC ?', '["Le CSAC", "La Cellule interministérielle de gestion des bourses à l’étranger", "La CENI", "L’ONIP"]'::jsonb, 1, 'La Cellule interministérielle de gestion des bourses à l’étranger a été créée par arrêté interministériel en 2023.', 'https://diplomatie.gouv.cd/2025/05/14/bourse-detudes/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1427', 'Congo contemporain', 'Éducation - bourses', 'En quelle année la Cellule interministérielle de gestion des bourses à l’étranger a-t-elle été créée ?', '["2018", "2025", "2020", "2023"]'::jsonb, 3, 'L’arrêté interministériel instituant la cellule est daté du 16 octobre 2023.', 'https://diplomatie.gouv.cd/2025/05/14/bourse-detudes/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1428', 'Congo contemporain', 'Éducation - bourses', 'Quel est l’un des objectifs de la Cellule interministérielle de gestion des bourses à l’étranger ?', '["Fixer le taux directeur", "Délivrer les passeports", "Améliorer la traçabilité des dossiers de bourses", "Organiser les élections"]'::jsonb, 2, 'La cellule vise notamment l’harmonisation et la traçabilité des demandes et du suivi des étudiants boursiers.', 'https://diplomatie.gouv.cd/2025/05/14/bourse-detudes/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1429', 'Congo contemporain', 'Éducation - bourses', 'Quel pays a annoncé en 2025 des bourses postuniversitaires destinées à des étudiants congolais via cette cellule ?', '["Les Émirats arabes unis", "Le Chili", "Le Pérou", "La Norvège"]'::jsonb, 0, 'Le ministère congolais des Affaires étrangères a publié en juillet 2025 une offre de bourses postuniversitaires des Émirats arabes unis.', 'https://diplomatie.gouv.cd/2025/07/30/bourses-detudes-postuniversitaires/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1430', 'Sport', 'Boxe - Rumble in the Jungle', 'Quels boxeurs se sont affrontés à Kinshasa lors du « Rumble in the Jungle » ?', '["Mike Tyson et Evander Holyfield", "Joe Frazier et Larry Holmes", "George Foreman et Mike Tyson", "Muhammad Ali et George Foreman"]'::jsonb, 3, 'Le combat du 30 octobre 1974 opposait Muhammad Ali à George Foreman.', 'https://www.history.com/this-day-in-history/october-30/muhammad-ali-wins-the-rumble-in-the-jungle', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1431', 'Sport', 'Boxe - Rumble in the Jungle', 'En quelle année a eu lieu le « Rumble in the Jungle » à Kinshasa ?', '["1978", "1984", "1974", "1968"]'::jsonb, 2, 'Le combat s’est déroulé le 30 octobre 1974.', 'https://www.history.com/this-day-in-history/october-30/muhammad-ali-wins-the-rumble-in-the-jungle', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1432', 'Sport', 'Boxe - Rumble in the Jungle', 'Dans quel pays se trouvait Kinshasa lors du combat Ali-Foreman de 1974 ?', '["La République du Congo", "Le Congo belge", "Le Zaïre", "Le Rwanda"]'::jsonb, 2, 'En 1974, la RDC portait le nom de République du Zaïre.', 'https://www.history.com/this-day-in-history/october-30/muhammad-ali-wins-the-rumble-in-the-jungle', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1433', 'Sport', 'Boxe - Rumble in the Jungle', 'Qui a remporté le combat Ali-Foreman à Kinshasa ?', '["George Foreman", "Le combat a été annulé", "Match nul", "Muhammad Ali"]'::jsonb, 3, 'Ali a remporté le combat par KO au huitième round.', 'https://www.history.com/this-day-in-history/october-30/muhammad-ali-wins-the-rumble-in-the-jungle', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1434', 'Sport', 'Boxe - Rumble in the Jungle', 'À quel round Muhammad Ali a-t-il battu George Foreman à Kinshasa ?', '["12e round", "2e round", "5e round", "8e round"]'::jsonb, 3, 'Ali a mis Foreman KO au huitième round.', 'https://www.history.com/this-day-in-history/october-30/muhammad-ali-wins-the-rumble-in-the-jungle', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1435', 'Sport', 'Boxe - Rumble in the Jungle', 'Comment s’appelait le stade où s’est tenu le combat Ali-Foreman en 1974 ?', '["Stade Kibassa Maliba", "Stade du 20 Mai", "Stade des Martyrs", "Stade Tata Raphaël dès 1974"]'::jsonb, 1, 'Le combat s’est tenu au Stade du 20 Mai, enceinte aujourd’hui connue comme le Stade Tata Raphaël.', 'https://www.history.com/this-day-in-history/october-30/muhammad-ali-wins-the-rumble-in-the-jungle', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1436', 'Sport', 'Boxe - Rumble in the Jungle', 'Quelle stratégie de Muhammad Ali est particulièrement associée au combat contre Foreman ?', '["Le tiki-taka", "Le coup de pied retourné", "Le « rope-a-dope »", "Le pressing tout-terrain"]'::jsonb, 2, 'Ali s’est appuyé sur les cordes pour absorber les attaques et fatiguer Foreman avant de contre-attaquer.', 'https://www.history.com/this-day-in-history/october-30/muhammad-ali-wins-the-rumble-in-the-jungle', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1437', 'Congo contemporain', 'Sport - Mike Tyson à Kinshasa', 'Quel ancien champion du monde poids lourds a séjourné à Kinshasa en octobre 2025 pour les commémorations du combat Ali-Foreman ?', '["Mike Tyson", "Lennox Lewis", "Anthony Joshua", "Oleksandr Usyk"]'::jsonb, 0, 'Mike Tyson a été reçu par le président Félix Tshisekedi lors de son séjour à Kinshasa en octobre 2025.', 'https://www.presidence.cd/actualite-detail/actualite/en_sejour_a_kinshasa_le_boxeur_mike_tyson_recu_par_le_president_felix_tshisekedi', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1438', 'Congo contemporain', 'Sport - Mike Tyson à Kinshasa', 'À quelle occasion Mike Tyson s’est-il rendu à Kinshasa en 2025 ?', '["La CAN", "Les célébrations du 50e anniversaire du combat Ali-Foreman", "L’inauguration d’un aéroport", "Un sommet de l’Union africaine"]'::jsonb, 1, 'Son séjour s’inscrivait dans les activités commémorant le cinquantenaire du Rumble in the Jungle.', 'https://www.presidence.cd/actualite-detail/actualite/en_sejour_a_kinshasa_le_boxeur_mike_tyson_recu_par_le_president_felix_tshisekedi', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1439', 'Congo contemporain', 'Sport - Mike Tyson à Kinshasa', 'Quelle déclaration personnelle Mike Tyson a-t-il faite pendant son séjour à Kinshasa en 2025 ?', '["Il a annoncé ouvrir une mine", "Il a demandé la nationalité belge", "Il a déclaré avoir des origines congolaises", "Il a annoncé devenir sélectionneur des Léopards"]'::jsonb, 2, 'La Présidence congolaise rapporte que Mike Tyson a déclaré ses origines congolaises lors de ce séjour ; cette déclaration personnelle ne constitue pas à elle seule une preuve généalogique.', 'https://www.presidence.cd/actualite-detail/actualite/en_sejour_a_kinshasa_le_boxeur_mike_tyson_recu_par_le_president_felix_tshisekedi', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1440', 'Congo contemporain', 'Diaspora et rayonnement culturel', 'Quels deux frères artistes de la diaspora ont présenté en 2022 un projet culturel au président Félix Tshisekedi ?', '["Gims et Dadju", "Fally Ipupa et Ferre Gola", "Werrason et JB Mpiana", "Youssou N’Dour et Akon"]'::jsonb, 0, 'Gims et Dadju ont présenté un projet visant à renforcer le rayonnement culturel de la RDC.', 'https://acp.cd/nation/deux-stars-congolaises-gims-et-dadju-presentent-au-chef-de-letat-felix-tshisekedi-leur-projet-culturel-pour-la-rdc/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1441', 'Congo contemporain', 'Diaspora et rayonnement culturel', 'Quel rôle Gims et Dadju ont-ils dit assumer pour la RDC à l’issue de leur audience de 2022 ?', '["Officiers de réserve", "Députés nationaux", "Gouverneurs honoraires", "Ambassadeurs culturels"]'::jsonb, 3, 'Les deux artistes ont indiqué endosser un rôle d’ambassadeurs culturels pour faire rayonner l’image du Congo.', 'https://acp.cd/nation/deux-stars-congolaises-gims-et-dadju-presentent-au-chef-de-letat-felix-tshisekedi-leur-projet-culturel-pour-la-rdc/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1442', 'Institutions & politique', 'Identification nationale', 'Quel est le sigle officiel de la Carte d’Identité Nationale en RDC ?', '["CIR", "CIN", "CIP", "CNI"]'::jsonb, 1, 'L’Office national d’identification de la population utilise le sigle CIN pour Carte d’Identité Nationale.', 'https://www.onip.gouv.cd/', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1443', 'Institutions & politique', 'Identification nationale', 'Quel organisme produit et délivre la Carte d’Identité Nationale congolaise ?', '["La CENI", "L’ONIP", "La Banque centrale", "Le CSAC"]'::jsonb, 1, 'La CIN est produite et délivrée par l’Office national d’identification de la population.', 'https://www.onip.gouv.cd/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1444', 'Institutions & politique', 'Identification nationale', 'Quelle est la fonction principale d’une Carte d’Identité Nationale ?', '["Donner le droit de vote à l’étranger", "Remplacer automatiquement le passeport", "Attester officiellement l’identité d’une personne", "Servir uniquement de permis de conduire"]'::jsonb, 2, 'La carte d’identité est un document administratif officiel destiné à attester l’identité de son titulaire.', 'https://www.onip.gouv.cd/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1445', 'Institutions & politique', 'Identification nationale', 'Quelle est la durée de validité annoncée par l’ONIP pour la CIN congolaise ?', '["20 ans", "5 ans", "2 ans", "10 ans"]'::jsonb, 3, 'L’ONIP indique une validité de dix ans.', 'https://www.onip.gouv.cd/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1446', 'Institutions & politique', 'Identification nationale', 'À partir de quel âge le port de la CIN est-il obligatoire selon les règles publiées par l’ONIP ?', '["12 ans", "18 ans", "16 ans", "21 ans"]'::jsonb, 1, 'Le port de la CIN est obligatoire pour tout Congolais âgé de 18 ans révolus.', 'https://www.onip.gouv.cd/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1447', 'Institutions & politique', 'Défense nationale', 'Comment s’appellent les forces armées nationales de la RDC ?', '["FARC", "FAC", "FARDC", "FAN"]'::jsonb, 2, 'FARDC signifie Forces armées de la République démocratique du Congo.', 'https://www.fardc.org/fr/army/', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1448', 'Institutions & politique', 'Défense nationale', 'Quelle est la mission fondamentale des FARDC ?', '["Administrer les universités", "Organiser les élections", "Défendre la souveraineté et l’intégrité territoriale du pays", "Gérer la monnaie"]'::jsonb, 2, 'Les FARDC sont chargées de défendre la souveraineté et l’intégrité territoriale de la RDC.', 'https://www.fardc.org/fr/army/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1449', 'Institutions & politique', 'Garde républicaine', 'Quelle est la mission spécifique principale de la Garde républicaine congolaise ?', '["Contrôler la Banque centrale", "Protéger le Chef de l’État et les installations présidentielles", "Diriger les provinces", "Organiser les élections"]'::jsonb, 1, 'La Garde républicaine assure notamment la protection du Chef de l’État, de sa famille, de ses hôtes et des installations présidentielles.', 'https://presidence.cd/actualite-detail/actualite/le_commandant_de_la_garde_republicaine_promet_la_mort_aux_traitres_de_la_garde_republicaine', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1450', 'Institutions & politique', 'Garde républicaine', 'La Garde républicaine peut-elle être engagée dans la défense de l’intégrité du territoire national ?', '["Uniquement hors de la RDC", "Seulement après un référendum", "Non, jamais", "Oui"]'::jsonb, 3, 'La Présidence indique que la GR peut être engagée, si nécessaire, dans la défense de l’intégrité du territoire.', 'https://presidence.cd/actualite-detail/actualite/le_commandant_de_la_garde_republicaine_promet_la_mort_aux_traitres_de_la_garde_republicaine', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1451', 'Institutions & politique', 'Symboles nationaux', 'Que symbolise la couleur bleue du drapeau de la RDC selon la Présidence ?', '["La paix et l’espoir", "Le sang des martyrs", "La forêt équatoriale", "Le cuivre"]'::jsonb, 0, 'La Présidence associe le bleu à la paix et à l’espoir.', 'https://presidence.cd/detail-symbole/1', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1452', 'Institutions & politique', 'Symboles nationaux', 'Que représente la bande rouge du drapeau congolais ?', '["Le fleuve Congo", "Le cobalt", "La forêt", "Le sang des martyrs"]'::jsonb, 3, 'Le rouge représente le sang des martyrs.', 'https://presidence.cd/detail-symbole/1', null, null, 1, 'valide') on conflict (id) do nothing;
