insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1454', 'Institutions & politique', 'Symboles nationaux', 'Que symbolise l’étoile jaune du drapeau de la RDC selon la Présidence ?', '["La monarchie belge", "Le bassin du Congo uniquement", "Une province particulière", "Un pays uni promis à un avenir radieux"]'::jsonb, 3, 'L’étoile jaune renvoie à l’unité du pays et à un avenir radieux.', 'https://presidence.cd/detail-symbole/1', null, null, 2, 'valide') on conflict (id) do nothing;
