insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1456', 'Sport', 'Stade des Martyrs', 'En quelle année le Stade des Martyrs a-t-il été inauguré ?', '["1994", "1974", "2004", "1984"]'::jsonb, 0, 'L’inauguration a eu lieu le 14 septembre 1994.', 'https://www.jeux.francophonie.org/sites/default/files/public/wysiwyg/brochure_cnjf50.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
