insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1465', 'Congo contemporain', 'Culture - Fally Ipupa', 'Quelle formulation officielle a été utilisée à propos de Fally Ipupa après ses concerts au Stade de France en 2026 ?', '["Premier artiste africain francophone évoluant en Afrique à s’y produire", "Premier artiste africain de l’histoire à entrer en France", "Premier Congolais à chanter en Europe", "Premier artiste africain à gagner un Grammy"]'::jsonb, 0, 'La Présidence a présenté Fally Ipupa comme le premier artiste africain francophone évoluant en Afrique à se produire au Stade de France.', 'https://www.presidence.cd/actualite-detail/actualite/eleve_au_grade_de_chevalier_de_lordre_national_des_leopards_le_chanteur_fally_ipupa_a_ete_decore_par_le_chef_de_letat', null, null, 4, 'valide') on conflict (id) do nothing;
