insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1473', 'Musique', 'Franco Luambo', 'Quel est le titre de la toute première chanson de Franco Luambo gravée sur disque selon Radio Okapi ?', '["Lili Madi chérie wa ngai", "Mario", "Mamou", "Attention na SIDA"]'::jsonb, 0, 'Radio Okapi rapporte que la première chanson de Franco gravée sur disque s’intitulait « Lili Madi chérie wa ngai ».', 'https://www.radiookapi.net/node/245938', null, null, 1, 'valide') on conflict (id) do nothing;
