insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1475', 'Musique', 'Madilu System', 'Quel était le nom civil de Madilu System ?', '["Jean de Dieu Bialu Makiese", "François Luambo Makiadi", "Jules Shungu Wembadio", "Antoine Christophe Agbepa"]'::jsonb, 0, 'Madilu System s’appelait Jean de Dieu Bialu Makiese. Il a notamment travaillé avec Tabu Ley, Pépé Kallé et Franco au sein de l’OK Jazz.', 'https://www.radiookapi.net/2018/08/20/actualite/culture/le-11-aout-2007-madilu-systeme-mourait-kinshasa', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1476', 'Musique', 'Koffi Olomidé', 'Quel album de Koffi Olomidé contient le titre « Loi » ?', '["Emotion", "Effrakata", "Loi", "Droit chemin"]'::jsonb, 2, 'L’album « Loi » est associé au morceau-titre devenu emblématique du ndombolo.', 'https://www.shazam.com/fr-fr/album/953596634/loi', null, null, 2, 'valide') on conflict (id) do nothing;
