insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1478', 'Musique', 'Werrason', 'Quel album de Werrason lui a valu un important succès aux Kora Awards au début des années 2000 ?', '["Loi", "Droit chemin", "Emotion", "Kibuisa Mpimpa"]'::jsonb, 3, 'Afrisson indique que l’album « Kibuisa Mpimpa » a valu à Werrason un prix de meilleur chanteur africain aux Kora Awards.', 'https://www.afrisson.com/werrason-5473/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1479', 'Musique', 'Werrason', 'Dans quel pays Werrason a-t-il reçu le Kora Award mentionné pour « Kibuisa Mpimpa » ?', '["Côte d’Ivoire", "France", "Afrique du Sud", "États-Unis"]'::jsonb, 2, 'La cérémonie des Kora Awards concernée s’est tenue à Sun City, en Afrique du Sud.', 'https://www.afrisson.com/werrason-5473/', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1480', 'Musique', 'Werrason', 'Quelle formule Werrason a-t-il dit avoir immédiatement corrigée après l’annulation d’un concert pour la paix ?', '["« Cultivons la haine »", "« Oublions la paix »", "« Vive la guerre »", "« Refusons le dialogue »"]'::jsonb, 0, 'Dans une interview rapportée en 2018, Werrason est revenu sur cette formule prononcée dans un contexte de mécontentement, en disant l’avoir immédiatement corrigée.', 'https://mbote.cd/celebrites/werrason-parlement-je-parlerai-francais-couramment-et-proprement/15454/', null, null, 5, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1481', 'Nature & environnement', 'Espèces endémiques', 'Quel mammifère emblématique est endémique de la RDC ?', '["L’okapi", "Le panda géant", "Le bison d’Europe", "Le koala"]'::jsonb, 0, 'La RDC abrite plusieurs espèces endémiques, dont l’okapi.', 'https://drcongo.wcs.org/', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1482', 'Nature & environnement', 'Espèces endémiques', 'Quel grand singe vit naturellement uniquement en RDC ?', '["Le gibbon", "L’orang-outan", "Le bonobo", "Le babouin hamadryas"]'::jsonb, 2, 'Le bonobo est une espèce endémique de la RDC.', 'https://drcongo.wcs.org/', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1483', 'Nature & environnement', 'Espèces endémiques', 'Quel gorille endémique de l’est de la RDC est également appelé gorille de Grauer ?', '["Le gorille de l’Ouest", "Le gorille de Cross River", "Le gorille des plaines de l’Est", "Le gorille albinos"]'::jsonb, 2, 'Le gorille de Grauer, ou gorille des plaines de l’Est, est une espèce emblématique de la biodiversité congolaise.', 'https://drcongo.wcs.org/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1484', 'Nature & environnement', 'Espèces endémiques', 'Quel oiseau endémique de la RDC porte le nom du pays ?', '["Le paon du Congo", "Le toucan du Congo", "Le flamant du Congo", "L’autruche du Congo"]'::jsonb, 0, 'Le paon du Congo fait partie des espèces endémiques citées par la Wildlife Conservation Society.', 'https://drcongo.wcs.org/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1485', 'Nature & environnement', 'Forêts du bassin du Congo', 'À quel rang mondial se situe la forêt pluviale du bassin du Congo par superficie ?', '["Dixième", "Première", "Quatrième", "Deuxième, derrière l’Amazonie"]'::jsonb, 3, 'Le bassin du Congo constitue la deuxième plus grande forêt pluviale de la planète après l’Amazonie.', 'https://www.wwf.fr/territoires/bassin-du-congo', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1486', 'Nature & environnement', 'Forêts du bassin du Congo', 'Environ quelle part des espèces de plantes tropicales du bassin du Congo serait unique à la région selon le WWF ?', '["3 %", "30 %", "70 %", "10 %"]'::jsonb, 1, 'Le WWF indique qu’environ 30 % des quelque 10 000 espèces de plantes tropicales de la région sont uniques au bassin.', 'https://www.wwf.fr/territoires/bassin-du-congo', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1487', 'Nature & environnement', 'Réserve de faune à okapis', 'Quelle forêt la Réserve de faune à okapis protège-t-elle en partie ?', '["La forêt de Nyungwe uniquement", "La forêt du Mayombe en totalité", "La forêt de Fontainebleau", "La forêt de l’Ituri"]'::jsonb, 3, 'La réserve occupe environ un cinquième de la forêt de l’Ituri.', 'https://whc.unesco.org/en/list/718', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1488', 'Géographie & 26 provinces', 'Relief', 'Quelle grande forme de relief domine le centre de la RDC ?', '["La cuvette centrale du Congo", "Une chaîne alpine continue", "Une vaste calotte glaciaire", "Un désert côtier"]'::jsonb, 0, 'Le centre et l’ouest du pays sont structurés autour d’une large cuvette, bordée de plateaux et de montagnes.', 'https://digitallibrary.un.org/record/790076/files/UNDP-CD-OMD-rapport-national.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1489', 'Géographie & 26 provinces', 'Relief', 'Dans quelle partie de la RDC trouve-t-on les reliefs les plus élevés et les plus accidentés ?', '["À l’extrême Ouest côtier", "Au centre de Kinshasa", "À l’Est", "Dans le bassin inférieur du Kasaï uniquement"]'::jsonb, 2, 'L’Est est marqué par des hauts plateaux, des chaînes montagneuses, des volcans et les grands lacs du Rift.', 'https://digitallibrary.un.org/record/790076/files/UNDP-CD-OMD-rapport-national.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1490', 'Géographie & 26 provinces', 'Climat', 'Quel type de climat domine autour de l’équateur en RDC ?', '["Équatorial humide", "Désertique froid", "Polaire", "Méditerranéen"]'::jsonb, 0, 'La cuvette centrale proche de l’équateur connaît un climat chaud et humide, avec des pluies abondantes.', 'https://digitallibrary.un.org/record/790076/files/UNDP-CD-OMD-rapport-national.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1491', 'Géographie & 26 provinces', 'Relief', 'Quelle grande structure tectonique marque l’Est de la RDC ?', '["La faille de San Andreas", "Le bouclier scandinave", "Le Rift est-africain, branche occidentale", "La dorsale médio-atlantique"]'::jsonb, 2, 'L’Est de la RDC se situe le long de la branche occidentale du Rift est-africain, aussi appelée Rift Albertin.', 'https://digitallibrary.un.org/record/790076/files/UNDP-CD-OMD-rapport-national.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1492', 'Géographie & 26 provinces', 'Volcanisme', 'Quel volcan actif domine la région de Goma ?', '["Nyiragongo", "Mont Cameroun", "Kilimandjaro", "Elgon"]'::jsonb, 0, 'Le Nyiragongo, dans les Virunga, est l’un des volcans actifs les plus connus de la RDC.', 'https://whc.unesco.org/en/congobiodiversity', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1493', 'Géographie & 26 provinces', 'Fleuve Congo', 'Quel est le rang du fleuve Congo par longueur en Afrique ?', '["Premier", "Cinquième", "Deuxième après le Nil", "Troisième"]'::jsonb, 2, 'Le fleuve Congo est le deuxième plus long fleuve d’Afrique après le Nil.', 'https://assets.publishing.service.gov.uk/media/57a08bd940f0b652dd000f22/TI_UP_HD_Apr2007_Hydro_Potential_of_Congo_River.pdf', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1494', 'Géographie & 26 provinces', 'Fleuve Congo', 'Quel est le rang mondial du fleuve Congo par débit moyen ?', '["Premier", "Deuxième derrière l’Amazone", "Cinquième", "Dixième"]'::jsonb, 1, 'Le fleuve Congo possède le deuxième débit moyen le plus élevé au monde, derrière l’Amazone.', 'https://assets.publishing.service.gov.uk/media/57a08bd940f0b652dd000f22/TI_UP_HD_Apr2007_Hydro_Potential_of_Congo_River.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1495', 'Géographie & 26 provinces', 'Fleuve Congo', 'Dans quel océan le fleuve Congo se jette-t-il ?', '["Océan Indien", "Océan Pacifique", "Mer Rouge", "Océan Atlantique"]'::jsonb, 3, 'Le fleuve Congo se jette dans l’océan Atlantique.', 'https://assets.publishing.service.gov.uk/media/57a08bd940f0b652dd000f22/TI_UP_HD_Apr2007_Hydro_Potential_of_Congo_River.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1496', 'Géographie & 26 provinces', 'Fleuve Congo', 'Pourquoi le débit du fleuve Congo est-il relativement régulier au cours de l’année ?', '["Il est alimenté uniquement par des glaciers", "Il ne reçoit aucun affluent", "Il est entièrement artificiel", "Son bassin s’étend des deux côtés de l’équateur"]'::jsonb, 3, 'Comme son bassin s’étend au nord et au sud de l’équateur, différentes zones connaissent leur saison des pluies à des moments différents.', 'https://assets.publishing.service.gov.uk/media/57a08bd940f0b652dd000f22/TI_UP_HD_Apr2007_Hydro_Potential_of_Congo_River.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1497', 'Géographie & 26 provinces', 'Anciens noms des villes', 'Quel était le nom colonial de Kinshasa ?', '["Léopoldville", "Coquilhatville", "Stanleyville", "Élisabethville"]'::jsonb, 0, 'Kinshasa était connue sous le nom de Léopoldville jusqu’en 1966.', 'https://www.larousse.fr/encyclopedie/ville/Kinshasa/127531', null, null, 1, 'valide') on conflict (id) do nothing;
