insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1499', 'Géographie & 26 provinces', 'Anciens noms des villes', 'Quel était l’ancien nom de Kisangani ?', '["Élisabethville", "Stanleyville", "Coquilhatville", "Luluabourg"]'::jsonb, 1, 'Kisangani était anciennement appelée Stanleyville.', 'https://www.larousse.fr/encyclopedie/ville/Kisangani/127575', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1500', 'Géographie & 26 provinces', 'Anciens noms des villes', 'Quel était l’ancien nom de Mbandaka ?', '["Banningville", "Albertville", "Léopoldville", "Coquilhatville"]'::jsonb, 3, 'Mbandaka était anciennement Coquilhatville.', 'https://www.larousse.fr/encyclopedie/ville/Mbandaka/132487', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1501', 'Géographie & 26 provinces', 'Anciens noms des villes', 'Quel était l’ancien nom de Kananga ?', '["Stanleyville", "Thysville", "Luluabourg", "Jadotville"]'::jsonb, 2, 'Kananga portait auparavant le nom de Luluabourg.', 'https://www.larousse.fr/encyclopedie/ville/Kananga/126504', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1502', 'Géographie & 26 provinces', 'Kinshasa - toponymie', 'Comment s’appelait autrefois l’actuel boulevard du 30 Juin à Kinshasa ?', '["Boulevard Baudouin-II", "Boulevard Stanley", "Boulevard Albert-Ier", "Boulevard Léopold-II"]'::jsonb, 2, 'Le boulevard du 30 Juin était auparavant le boulevard Albert-Ier.', 'https://www.lemonde.fr/archives/article/1978/05/31/kinshasa-un-district-urbain-plus-vaste-que-la-belgique_2979483_1819218.html', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1503', 'Géographie & 26 provinces', 'Kinshasa - toponymie', 'À quelle date nationale le boulevard du 30 Juin doit-il son nom ?', '["La création du MPR", "L’indépendance du 30 juin 1960", "La victoire à la CAN 1974", "La naissance de Mobutu"]'::jsonb, 1, 'Son nom rappelle la date de l’indépendance de la RDC.', 'https://www.lemonde.fr/archives/article/1978/05/31/kinshasa-un-district-urbain-plus-vaste-que-la-belgique_2979483_1819218.html', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1504', 'Congo contemporain', 'Transport aérien', 'Quelle nouvelle compagnie aérienne a été lancée en partenariat entre l’État congolais et Ethiopian Airlines en décembre 2024 ?', '["Congo Express Europe", "Air Congo", "Katanga Airways", "Zaïre Air 2"]'::jsonb, 1, 'Air Congo a été créée dans le cadre d’un partenariat entre le gouvernement de la RDC et Ethiopian Airlines.', 'https://corporate.ethiopianairlines.com/Press-release-open-page/ethiopian-airlines-partners-with-drc-government-to-launch-air-congo', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1505', 'Congo contemporain', 'Transport aérien', 'Quelle part du capital d’Air Congo est détenue par l’État congolais selon l’accord de lancement ?', '["49 %", "51 %", "25 %", "75 %"]'::jsonb, 1, 'Le gouvernement de la RDC détient 51 % d’Air Congo.', 'https://corporate.ethiopianairlines.com/Press-release-open-page/ethiopian-airlines-partners-with-drc-government-to-launch-air-congo', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1506', 'Congo contemporain', 'Transport aérien', 'Quelle part d’Air Congo est détenue par Ethiopian Airlines ?', '["49 %", "30 %", "51 %", "10 %"]'::jsonb, 0, 'Ethiopian Airlines détient 49 % et assure la gestion de la compagnie.', 'https://corporate.ethiopianairlines.com/Press-release-open-page/ethiopian-airlines-partners-with-drc-government-to-launch-air-congo', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1507', 'Histoire', 'Mémoire coloniale', 'En quelle année le roi Philippe de Belgique a-t-il exprimé pour la première fois ses « plus profonds regrets » concernant les violences de la période coloniale ?', '["2020", "2010", "2022", "2000"]'::jsonb, 0, 'Le roi Philippe a exprimé ses plus profonds regrets dans une lettre adressée au président Félix Tshisekedi le 30 juin 2020.', 'https://www.vrt.be/vrtnws/fr/2020/06/30/le-roi-philippe-exprime-ses-plus-profonds-regrets-pour-les-sou/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1508', 'Histoire', 'Mémoire coloniale', 'Le roi Philippe a-t-il présenté des excuses formelles dans sa lettre de 2020 sur le passé colonial ?', '["Uniquement au Parlement congolais en 2020", "Oui, au nom de Léopold II", "Non", "Oui"]'::jsonb, 2, 'Le souverain a exprimé ses « plus profonds regrets », mais le texte ne constitue pas des excuses formelles.', 'https://www.vrt.be/vrtnws/fr/2020/06/30/le-roi-philippe-exprime-ses-plus-profonds-regrets-pour-les-sou/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1509', 'Histoire', 'Patrice Lumumba - mémoire', 'En quelle année la Belgique a-t-elle remis à la famille de Patrice Lumumba la dent présentée comme son seul reste connu ?', '["2022", "2002", "2012", "2025"]'::jsonb, 0, 'La dent a été remise à la famille lors d’une cérémonie à Bruxelles le 20 juin 2022.', 'https://www.reutersconnect.com/item/belgium-returns-remains-of-democratic-republic-of-congos-first-pm-lumumba-in-brussels/dGFnOnJldXRlcnMuY29tLDIwMjI6bmV3c21sX1JDMk1WVTlWTzBPTQ', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1510', 'Histoire', 'Patrice Lumumba - mémoire', 'Quel type de relique de Patrice Lumumba a été restitué par la Belgique en 2022 ?', '["Un uniforme", "Une montre", "Une dent", "Une mèche de cheveux"]'::jsonb, 2, 'Une dent conservée en Belgique a été remise à la famille de Patrice Lumumba.', 'https://www.reutersconnect.com/item/belgium-returns-remains-of-democratic-republic-of-congos-first-pm-lumumba-in-brussels/dGFnOnJldXRlcnMuY29tLDIwMjI6bmV3c21sX1JDMk1WVTlWTzBPTQ', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1511', 'Congo contemporain', 'Religions en RDC', 'Selon l’estimation 2020 de la World Religion Database citée par le Département d’État américain, environ quelle part de la population de la RDC est chrétienne ?', '["Environ 55 %", "Environ 70 %", "Environ 95 %", "Pratiquement 100 %"]'::jsonb, 2, 'La source cite une estimation de 95,1 % de chrétiens. Il s’agit d’une estimation démographique, pas d’un recensement religieux exhaustif.', 'https://2021-2025.state.gov/reports/2023-report-on-international-religious-freedom/democratic-republic-of-the-congo/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1512', 'Congo contemporain', 'Religions en RDC', 'Dans cette même estimation 2020, quelle part de la population congolaise est musulmane ?', '["Environ 1,5 %", "Environ 10 %", "Environ 20 %", "Environ 35 %"]'::jsonb, 0, 'La World Religion Database estimait à 1,5 % la part musulmane. Des responsables musulmans avancent cependant des estimations plus élevées, autour de 5 %.', 'https://2021-2025.state.gov/reports/2023-report-on-international-religious-freedom/democratic-republic-of-the-congo/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1513', 'Congo contemporain', 'Religions en RDC', 'Quelle part de la population de RDC était estimée sans affiliation religieuse par la World Religion Database en 2020 ?', '["0,2 %", "2,5 %", "12,5 %", "25 %"]'::jsonb, 1, 'L’estimation citée est de 2,5 % de personnes sans affiliation religieuse.', 'https://2021-2025.state.gov/reports/2023-report-on-international-religious-freedom/democratic-republic-of-the-congo/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1514', 'Art, coutumes & patrimoine', 'Religions en RDC', 'Selon l’estimation Pew de 2010 citée dans le rapport américain sur la liberté religieuse, quel courant représentait environ 48,1 % des chrétiens de RDC ?', '["Les protestants, y compris évangéliques et kimbanguistes", "Les orthodoxes", "Les musulmans", "Les baha’is"]'::jsonb, 0, 'Pew estimait que 48,1 % des chrétiens étaient protestants, catégorie comprenant notamment les évangéliques et les kimbanguistes dans cette source.', 'https://2021-2025.state.gov/reports/2023-report-on-international-religious-freedom/democratic-republic-of-the-congo/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1515', 'Art, coutumes & patrimoine', 'Religions en RDC', 'Selon cette estimation Pew de 2010, quelle part des chrétiens de RDC était catholique romaine ?', '["Environ 17,3 %", "Environ 27,3 %", "Environ 47,3 %", "Environ 77,3 %"]'::jsonb, 2, 'La proportion citée est de 47,3 % parmi les chrétiens.', 'https://2021-2025.state.gov/reports/2023-report-on-international-religious-freedom/democratic-republic-of-the-congo/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1516', 'Art, coutumes & patrimoine', 'Religions en RDC', 'Quelle affirmation décrit le mieux la diversité religieuse en RDC ?', '["Il n’existe qu’une seule religion reconnue", "Le pays est presque exclusivement divisé entre deux confessions", "On y trouve de nombreuses confessions chrétiennes, l’islam et de petites communautés d’autres religions", "Toutes les religions traditionnelles ont disparu"]'::jsonb, 2, 'La RDC présente une forte diversité interne au christianisme, une présence musulmane et de petites communautés hindoues, juives, bouddhistes, baha’ies et de religions autochtones.', 'https://2021-2025.state.gov/reports/2023-report-on-international-religious-freedom/democratic-republic-of-the-congo/', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1517', 'Congo contemporain', 'Religions en RDC', 'Pourquoi faut-il être prudent lorsqu’on demande « combien de religions » existent exactement en RDC ?', '["Parce que toute religion y est clandestine", "Parce qu’il n’existe pas de décompte officiel unique et les appartenances sont très diverses", "Parce que seule la religion du chef de l’État est comptée", "Parce que la Constitution interdit les statistiques"]'::jsonb, 1, 'Les sources donnent des estimations par grands courants et dénominations, mais pas un nombre officiel unique de « religions ».', 'https://2021-2025.state.gov/reports/2023-report-on-international-religious-freedom/democratic-republic-of-the-congo/', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1518', 'Personnages', 'Simon Kimbangu', 'Qui était Simon Kimbangu dans l’histoire religieuse congolaise ?', '["Un gouverneur colonial", "Un prophète et prédicateur congolais à l’origine du mouvement kimbanguiste", "Un roi du Kasaï", "Un cardinal belge"]'::jsonb, 1, 'Simon Kimbangu est la figure fondatrice du mouvement devenu l’Église kimbanguiste.', 'https://www.encyclopedia.com/people/history/british-and-irish-history-biographies/simon-kimbangu', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1519', 'Histoire', 'Simon Kimbangu', 'En quelle année commence la prédication publique de Simon Kimbangu qui donne naissance au mouvement kimbanguiste ?', '["1885", "1908", "1921", "1960"]'::jsonb, 2, 'L’année 1921 marque le début de son ministère public et l’essor du mouvement.', 'https://www.encyclopedia.com/people/history/british-and-irish-history-biographies/simon-kimbangu', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1520', 'Histoire', 'Simon Kimbangu', 'Quelle date est particulièrement commémorée dans l’histoire kimbanguiste comme début de la mission de Simon Kimbangu ?', '["4 janvier 1959", "6 avril 1921", "30 juin 1960", "17 mai 1997"]'::jsonb, 1, 'L’Église kimbanguiste situe le début de sa mission au 6 avril 1921.', 'https://www.oski.cd/eglise/', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1521', 'Géographie & 26 provinces', 'Simon Kimbangu', 'Quel village du Kongo Central est associé à Simon Kimbangu et constitue un grand lieu de pèlerinage kimbanguiste ?', '["Nkamba", "Bunia", "Mbuji-Mayi", "Kalemie"]'::jsonb, 0, 'Nkamba, lieu associé à Simon Kimbangu, occupe une place centrale dans le kimbanguisme.', 'https://www.encyclopedia.com/people/history/british-and-irish-history-biographies/simon-kimbangu', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1522', 'Histoire', 'Simon Kimbangu', 'Que lui arrive-t-il le 12 septembre 1921 ?', '["Il devient Premier ministre", "Il est arrêté par l’autorité coloniale", "Il proclame l’indépendance", "Il fonde l’ABAKO"]'::jsonb, 1, 'Simon Kimbangu se rend aux autorités et est arrêté en septembre 1921.', 'https://www.encyclopedia.com/people/history/british-and-irish-history-biographies/simon-kimbangu', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1523', 'Histoire', 'Simon Kimbangu', 'Quelle peine un tribunal colonial prononce-t-il contre Simon Kimbangu en octobre 1921 ?', '["Une amende", "L’exil en Belgique", "La peine de mort", "Cinq ans de prison"]'::jsonb, 2, 'Il est condamné à mort ; la peine sera ensuite commuée en emprisonnement à vie.', 'https://www.encyclopedia.com/people/history/british-and-irish-history-biographies/simon-kimbangu', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1524', 'Histoire', 'Simon Kimbangu', 'Que devient la peine de mort prononcée contre Simon Kimbangu ?', '["Elle est immédiatement exécutée", "Elle est commuée en emprisonnement à vie", "Elle devient une simple amende", "Elle est annulée le même jour"]'::jsonb, 1, 'La peine de mort est commuée en emprisonnement à vie par les autorités coloniales.', 'https://www.encyclopedia.com/people/history/british-and-irish-history-biographies/simon-kimbangu', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1525', 'Histoire', 'Simon Kimbangu', 'Dans quelle ville Simon Kimbangu meurt-il en détention en 1951 ?', '["Élisabethville, actuelle Lubumbashi", "Léopoldville, actuelle Kinshasa", "Stanleyville, actuelle Kisangani", "Coquilhatville, actuelle Mbandaka"]'::jsonb, 0, 'Il meurt en détention à Élisabethville, aujourd’hui Lubumbashi, en octobre 1951.', 'https://www.encyclopedia.com/people/history/british-and-irish-history-biographies/simon-kimbangu', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1526', 'Histoire', 'Kimbanguisme', 'En quelle année l’Église kimbanguiste obtient-elle sa reconnaissance légale à la fin de la période coloniale ?', '["1921", "1945", "1959", "1971"]'::jsonb, 2, 'Le mouvement, longtemps réprimé, obtient une reconnaissance légale en 1959.', 'https://www.encyclopedia.com/people/history/british-and-irish-history-biographies/simon-kimbangu', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1527', 'Art, coutumes & patrimoine', 'Kimbanguisme', 'Quel est le nom complet couramment utilisé pour l’Église kimbanguiste ?', '["Église de Jésus-Christ sur la Terre par son envoyé spécial Simon Kimbangu", "Église nationale du Congo belge", "Ordre religieux de Léopoldville", "Communauté catholique de Nkamba"]'::jsonb, 0, 'Le mouvement est connu comme l’Église de Jésus-Christ sur la Terre par son envoyé spécial Simon Kimbangu, souvent désignée comme Église kimbanguiste.', 'https://www.oski.cd/eglise/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1528', 'Congo contemporain', 'LAMUKA et opposition', 'Dans quelle ville l’accord ayant créé la coalition LAMUKA est-il conclu en novembre 2018 ?', '["Kinshasa", "Genève", "Bruxelles", "Addis-Abeba"]'::jsonb, 1, 'Les dirigeants de l’opposition se réunissent à Genève en novembre 2018.', 'https://www.radiookapi.net/node/186595', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1529', 'Congo contemporain', 'LAMUKA et opposition', 'Quel candidat est désigné candidat commun de l’opposition lors de l’accord de Genève du 11 novembre 2018 ?', '["Martin Fayulu", "Moïse Katumbi", "Jean-Pierre Bemba", "Emmanuel Ramazani Shadary"]'::jsonb, 0, 'Martin Fayulu est désigné candidat commun par les dirigeants réunis à Genève.', 'https://www.radiookapi.net/node/186595', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1530', 'Congo contemporain', 'LAMUKA et opposition', 'Quel était l’objectif électoral central à l’origine de LAMUKA en 2018 ?', '["Présenter un candidat commun de l’opposition à la présidentielle", "Supprimer l’élection présidentielle", "Créer une nouvelle province", "Remplacer la CENI par le Sénat"]'::jsonb, 0, 'La coalition est créée dans la recherche d’une candidature commune de l’opposition à la présidentielle.', 'https://documents.un.org/doc/undoc/gen/g19/068/88/pdf/g1906888.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1531', 'Congo contemporain', 'LAMUKA et opposition', 'Laquelle de ces personnalités faisait partie des dirigeants engagés dans la démarche de candidature commune ayant conduit à LAMUKA ?', '["Moïse Katumbi", "Joseph Kabila", "Augustin Kabuya", "Jeanine Mabunda"]'::jsonb, 0, 'Moïse Katumbi faisait partie des principaux dirigeants de l’opposition participant à cette démarche.', 'https://documents.un.org/doc/undoc/gen/g19/068/88/pdf/g1906888.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1532', 'Congo contemporain', 'LAMUKA et opposition', 'Quel ancien vice-président et dirigeant du MLC participait à la coalition LAMUKA en 2018 ?', '["Jean-Pierre Bemba", "Léon Kengo wa Dondo", "Joseph Olenghankoy", "Adolphe Lumanu"]'::jsonb, 0, 'Jean-Pierre Bemba, dirigeant du MLC, faisait partie des grandes figures associées à LAMUKA.', 'https://documents.un.org/doc/undoc/gen/g19/068/88/pdf/g1906888.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1533', 'Congo contemporain', 'LAMUKA et opposition', 'Quel ancien Premier ministre figurait parmi les dirigeants de l’opposition associés à LAMUKA en 2018 ?', '["Adolphe Muzito", "Matata Ponyo uniquement", "Samy Badibanga uniquement", "Bruno Tshibala uniquement"]'::jsonb, 0, 'Adolphe Muzito faisait partie des dirigeants engagés dans la démarche de candidature commune.', 'https://documents.un.org/doc/undoc/gen/g19/068/88/pdf/g1906888.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1534', 'Congo contemporain', 'LAMUKA et opposition', 'Quel rôle Olivier Kamitatu a-t-il notamment exercé dans la campagne de Martin Fayulu en 2018 ?', '["Responsable communication et NTIC", "Président de la CENI", "Président de la Cour constitutionnelle", "Chef d’état-major"]'::jsonb, 0, 'Dans l’organisation de campagne de LAMUKA, Olivier Kamitatu était chargé de la communication et des NTIC.', 'https://www.radiookapi.net/2018/11/27/actualite/revue-de-presse/la-prosperite-lamuka-passe-loffensive-fayulu-pierre-lumbi-la', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1535', 'Congo contemporain', 'LAMUKA et opposition', 'Olivier Kamitatu était-il l’un des sept dirigeants ayant signé l’accord de Genève désignant Martin Fayulu candidat commun ?', '["Oui, il faisait partie des sept dirigeants", "Non, il était un proche de Moïse Katumbi et acteur de la campagne, mais pas l’un des sept dirigeants de Genève", "Oui, en tant que président de la CENI", "Non, car il soutenait le FCC"]'::jsonb, 1, 'Olivier Kamitatu a joué un rôle important auprès de Moïse Katumbi et dans la campagne de LAMUKA, mais il n’était pas l’un des sept dirigeants réunis pour l’accord de Genève.', 'https://www.radiookapi.net/node/186595', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1536', 'Congo contemporain', 'Élections présidentielles', 'À quelle date s’est tenue l’élection présidentielle dont les résultats ont conduit à l’arrivée de Félix Tshisekedi à la présidence en janvier 2019 ?', '["30 décembre 2018", "10 janvier 2019", "30 décembre 2019", "20 décembre 2023"]'::jsonb, 0, 'Le scrutin présidentiel a eu lieu le 30 décembre 2018 ; les résultats ont été annoncés en janvier 2019.', 'https://www.radiookapi.net/2019/01/21/actualite/politique/elections-2018-la-cour-constitutionnelle-confirme-felix-tshisekedi', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1537', 'Congo contemporain', 'Élections présidentielles', 'Selon les résultats définitifs officiels de l’élection présidentielle de 2018, quel candidat a été proclamé vainqueur ?', '["Martin Fayulu", "Félix Tshisekedi", "Emmanuel Ramazani Shadary", "Moïse Katumbi"]'::jsonb, 1, 'La Cour constitutionnelle a confirmé Félix Tshisekedi vainqueur. Martin Fayulu a contesté ces résultats.', 'https://www.radiookapi.net/2019/01/21/actualite/politique/elections-2018-la-cour-constitutionnelle-confirme-felix-tshisekedi', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1538', 'Congo contemporain', 'Élections présidentielles', 'Selon les résultats définitifs officiels confirmés par la Cour constitutionnelle en janvier 2019, quel pourcentage a obtenu Félix Tshisekedi ?', '["18,57 %", "28,57 %", "38,57 %", "58,57 %"]'::jsonb, 2, 'La Cour constitutionnelle a confirmé le score officiel de 38,57 % pour Félix Tshisekedi.', 'https://www.radiookapi.net/2019/01/21/actualite/politique/elections-2018-la-cour-constitutionnelle-confirme-felix-tshisekedi', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1539', 'Congo contemporain', 'Élections présidentielles', 'Quel candidat a contesté les résultats officiels de la présidentielle de 2018 et demandé notamment un recomptage ?', '["Martin Fayulu", "Joseph Kabila", "Jeanine Mabunda", "Alexis Thambwe Mwamba"]'::jsonb, 0, 'Martin Fayulu a introduit un recours et contesté les résultats officiels proclamés.', 'https://www.radiookapi.net/2019/01/21/actualite/politique/elections-2018-la-cour-constitutionnelle-confirme-felix-tshisekedi', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1540', 'Congo contemporain', 'Élections présidentielles', 'À quelle date s’est tenue la présidentielle congolaise suivante, remportée officiellement par Félix Tshisekedi pour un second mandat ?', '["20 décembre 2023", "20 décembre 2024", "9 janvier 2024", "30 juin 2023"]'::jsonb, 0, 'La présidentielle suivante s’est tenue le 20 décembre 2023 ; les résultats définitifs ont été confirmés en janvier 2024.', 'https://presidence.cd/actualite-detail/actualite/election_presidentielle_2023_felix_tshisekedi_proclame_vainqueur_par_la_cour_constitutionnelle', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1541', 'Congo contemporain', 'Élections présidentielles', 'Selon les résultats définitifs officiels de la présidentielle du 20 décembre 2023, quel candidat a été proclamé vainqueur ?', '["Moïse Katumbi", "Martin Fayulu", "Félix Tshisekedi", "Denis Mukwege"]'::jsonb, 2, 'La Cour constitutionnelle a confirmé la réélection de Félix Tshisekedi.', 'https://presidence.cd/actualite-detail/actualite/election_presidentielle_2023_felix_tshisekedi_proclame_vainqueur_par_la_cour_constitutionnelle', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1542', 'Congo contemporain', 'Élections présidentielles', 'Quel score définitif officiel la Cour constitutionnelle a-t-elle attribué à Félix Tshisekedi pour la présidentielle de 2023 ?', '["38,57 %", "53,47 %", "63,47 %", "73,47 %"]'::jsonb, 3, 'La Cour constitutionnelle a proclamé un score définitif de 73,47 %.', 'https://presidence.cd/actualite-detail/actualite/election_presidentielle_2023_felix_tshisekedi_proclame_vainqueur_par_la_cour_constitutionnelle', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1543', 'Congo contemporain', 'Élections présidentielles', 'Selon les résultats provisoires de la CENI en 2023, quel candidat arrive deuxième derrière Félix Tshisekedi ?', '["Martin Fayulu", "Moïse Katumbi", "Denis Mukwege", "Adolphe Muzito"]'::jsonb, 1, 'La CENI a donné Moïse Katumbi deuxième avec 18,08 % des suffrages provisoires.', 'https://www.radiookapi.net/2023/12/31/actualite/politique/felix-tshisekedi-reelu-la-tete-de-la-rdc-pour-les-5-prochaines-annees', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1544', 'Congo contemporain', 'Élections présidentielles', 'Selon les résultats provisoires de la CENI en 2023, quel score obtient Moïse Katumbi ?', '["5,33 %", "18,08 %", "28,08 %", "38,08 %"]'::jsonb, 1, 'La CENI a annoncé 18,08 % pour Moïse Katumbi.', 'https://www.radiookapi.net/2023/12/31/actualite/politique/felix-tshisekedi-reelu-la-tete-de-la-rdc-pour-les-5-prochaines-annees', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1545', 'Congo contemporain', 'Élections présidentielles', 'Selon les résultats provisoires de la CENI en 2023, quel score obtient Martin Fayulu ?', '["5,33 %", "15,33 %", "25,33 %", "35,33 %"]'::jsonb, 0, 'La CENI a annoncé 5,33 % pour Martin Fayulu.', 'https://www.radiookapi.net/2023/12/31/actualite/politique/felix-tshisekedi-reelu-la-tete-de-la-rdc-pour-les-5-prochaines-annees', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1546', 'Institutions & politique', 'Constitution et régime politique', 'Selon l’article 1er de la Constitution, comment la RDC est-elle définie ?', '["Un État fédéral monarchique", "Un État de droit, indépendant, souverain, uni et indivisible", "Une confédération de provinces souveraines", "Un État sans Constitution écrite"]'::jsonb, 1, 'L’article 1er qualifie la RDC d’État de droit, indépendant, souverain, uni et indivisible, social, démocratique et laïc.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1547', 'Institutions & politique', 'Constitution et régime politique', 'La RDC est-elle constitutionnellement un État fédéral ?', '["Oui, explicitement", "Non : la Constitution la qualifie d’État uni et indivisible, tout en organisant la décentralisation", "Oui, mais seulement en période électorale", "La Constitution ne dit rien sur la forme de l’État"]'::jsonb, 1, 'La Constitution retient un État uni et indivisible et reconnaît d’importantes compétences aux provinces et aux entités décentralisées.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1548', 'Institutions & politique', 'Élection présidentielle', 'Depuis la révision constitutionnelle de 2011, comment le président de la RDC est-il élu ?', '["À deux tours obligatoires", "À la majorité simple des suffrages exprimés", "Par le Sénat", "Par les gouverneurs"]'::jsonb, 1, 'L’article 71 révisé prévoit l’élection à la majorité simple des suffrages exprimés.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1549', 'Institutions & politique', 'Élection présidentielle', 'Quel article de la Constitution fixe aujourd’hui l’élection présidentielle à la majorité simple des suffrages exprimés ?', '["Article 1", "Article 10", "Article 71", "Article 218"]'::jsonb, 2, 'Il s’agit de l’article 71, modifié lors de la révision de 2011.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1550', 'Institutions & politique', 'Président de la République', 'Quelle est la durée constitutionnelle d’un mandat présidentiel en RDC ?', '["4 ans", "5 ans", "6 ans", "7 ans"]'::jsonb, 1, 'L’article 70 prévoit un mandat de cinq ans, renouvelable une seule fois.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1551', 'Institutions & politique', 'Président de la République', 'Combien de fois le mandat présidentiel de cinq ans peut-il être renouvelé selon l’article 70 ?', '["Aucune", "Une seule fois", "Deux fois", "Sans limitation"]'::jsonb, 1, 'La Constitution autorise un seul renouvellement.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1552', 'Institutions & politique', 'Président de la République', 'Quel rôle l’article 69 attribue-t-il notamment au Président de la République ?', '["Chef de l’État et symbole de l’unité nationale", "Chef du pouvoir judiciaire", "Président automatique du Sénat", "Bourgmestre de Kinshasa"]'::jsonb, 0, 'L’article 69 fait du Président le chef de l’État, représentant de la Nation et symbole de l’unité nationale.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1553', 'Institutions & politique', 'Président de la République', 'Qui nomme le Premier ministre selon l’article 78 de la Constitution ?', '["Le Président de la République, au sein de la majorité parlementaire après consultation de celle-ci", "Le président du Sénat seul", "La Cour constitutionnelle", "Les gouverneurs"]'::jsonb, 0, 'Le Président nomme le Premier ministre au sein de la majorité parlementaire après consultation de celle-ci.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1554', 'Institutions & politique', 'Président de la République', 'Qui est constitutionnellement le commandant suprême des Forces armées de la RDC ?', '["Le Premier ministre", "Le président de l’Assemblée nationale", "Le Président de la République", "Le ministre de la Justice"]'::jsonb, 2, 'L’article 83 fait du Président de la République le commandant suprême des Forces armées.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1555', 'Institutions & politique', 'Président de la République', 'Le Président de la République peut-il déclarer seul la guerre, sans intervention du Parlement ?', '["Oui, toujours", "Non : l’autorisation de l’Assemblée nationale et du Sénat est requise, avec les autres conditions prévues par la Constitution", "Oui, si le gouverneur de Kinshasa accepte", "Non, car seul le Premier ministre peut déclarer la guerre"]'::jsonb, 1, 'L’article 86 prévoit une ordonnance délibérée en Conseil des ministres, après avis du Conseil supérieur de la défense et autorisation des deux Chambres.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1556', 'Institutions & politique', 'Président de la République', 'Quel article de la Constitution encadre la déclaration de guerre par le Président de la République ?', '["Article 10", "Article 71", "Article 86", "Article 220"]'::jsonb, 2, 'L’article 86 encadre la déclaration de guerre.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1557', 'Institutions & politique', 'Gouvernement', 'Avant d’entrer en fonction, que doit faire le Premier ministre devant l’Assemblée nationale ?', '["Présenter le programme du Gouvernement", "Dissoudre le Sénat", "Prêter serment comme gouverneur", "Organiser un référendum"]'::jsonb, 0, 'Le Premier ministre présente le programme du Gouvernement ; son approbation à la majorité absolue investit le Gouvernement.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1558', 'Institutions & politique', 'Gouvernement', 'Qui conduit la politique de la Nation selon l’article 91 ?', '["La Cour constitutionnelle", "Le Gouvernement", "La CENI", "La Banque centrale"]'::jsonb, 1, 'Le Gouvernement conduit la politique de la Nation et en assume la responsabilité.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1559', 'Institutions & politique', 'Gouvernement', 'Devant quelle institution le Gouvernement est-il politiquement responsable ?', '["La Cour de cassation", "L’Assemblée nationale", "Les assemblées provinciales réunies", "La CENI"]'::jsonb, 1, 'L’article 91 prévoit que le Gouvernement est responsable devant l’Assemblée nationale.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1560', 'Institutions & politique', 'Gouvernement', 'Quel pouvoir l’article 92 reconnaît-il au Premier ministre ?', '["Le pouvoir réglementaire, sous réserve des prérogatives du Président", "Le pouvoir de réviser seul la Constitution", "Le pouvoir de dissoudre le Sénat", "Le pouvoir de nommer tous les magistrats sans proposition"]'::jsonb, 0, 'Le Premier ministre assure l’exécution des lois et dispose du pouvoir réglementaire dans les limites constitutionnelles.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1561', 'Institutions & politique', 'Révision constitutionnelle', 'Quel article de la Constitution organise principalement la procédure de révision constitutionnelle ?', '["Article 71", "Article 100", "Article 218", "Article 226"]'::jsonb, 2, 'La procédure est organisée à l’article 218.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1562', 'Institutions & politique', 'Révision constitutionnelle', 'Lequel de ces acteurs peut prendre l’initiative d’une révision constitutionnelle en RDC ?', '["Le Président de la République", "Uniquement la Cour constitutionnelle", "Uniquement la CENI", "Uniquement les gouverneurs"]'::jsonb, 0, 'L’article 218 permet notamment au Président de la République d’initier une révision.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1563', 'Institutions & politique', 'Révision constitutionnelle', 'Combien de citoyens peuvent, par pétition, prendre l’initiative d’une révision constitutionnelle selon l’article 218 ?', '["10 000", "50 000", "100 000", "1 000 000"]'::jsonb, 2, 'La Constitution fixe ce seuil à 100 000 personnes.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1564', 'Institutions & politique', 'Révision constitutionnelle', 'À quelle majorité l’Assemblée nationale et le Sénat doivent-ils d’abord juger fondée une initiative de révision constitutionnelle ?', '["Majorité simple des présents", "Majorité absolue de chaque Chambre", "Deux tiers de chaque Chambre", "Unanimité"]'::jsonb, 1, 'L’article 218 exige à ce stade la majorité absolue de chaque Chambre.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 5, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1565', 'Institutions & politique', 'Révision constitutionnelle', 'Une révision constitutionnelle doit-elle toujours être soumise à référendum ?', '["Oui, sans aucune exception", "Non : le référendum peut être évité si le Congrès l’approuve à la majorité des trois cinquièmes", "Non : le Président décide seul", "Non : une majorité simple du Sénat suffit"]'::jsonb, 1, 'L’article 218 prévoit l’exception d’une approbation par le Congrès à la majorité des trois cinquièmes.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 5, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1566', 'Institutions & politique', 'Révision constitutionnelle', 'Quel article protège certaines matières contre toute révision constitutionnelle ?', '["Article 14", "Article 86", "Article 197", "Article 220"]'::jsonb, 3, 'L’article 220 contient les principales clauses dites intangibles.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1567', 'Institutions & politique', 'Révision constitutionnelle', 'Laquelle de ces matières ne peut pas faire l’objet d’une révision constitutionnelle selon l’article 220 ?', '["Le nombre et la durée des mandats présidentiels", "Le nom d’un ministère", "Le calendrier budgétaire ordinaire", "L’organisation interne d’une entreprise publique"]'::jsonb, 0, 'L’article 220 protège notamment le nombre et la durée des mandats du Président.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1568', 'Institutions & politique', 'Révision constitutionnelle', 'Peut-on réviser la Constitution pendant un état de guerre ?', '["Oui, sans restriction", "Non", "Seulement la nuit", "Seulement par décret du Premier ministre"]'::jsonb, 1, 'L’article 219 interdit notamment toute révision pendant l’état de guerre, l’état d’urgence ou l’état de siège.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1569', 'Institutions & politique', 'Parlement', 'Le Parlement de la RDC est composé de combien de chambres ?', '["Une", "Deux", "Trois", "Quatre"]'::jsonb, 1, 'Le Parlement est bicaméral : Assemblée nationale et Sénat.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1570', 'Institutions & politique', 'Parlement', 'Quel est l’un des rôles fondamentaux du Parlement selon l’article 100 ?', '["Voter les lois et contrôler le Gouvernement", "Commander directement les FARDC", "Nommer tous les bourgmestres", "Diriger la Banque centrale"]'::jsonb, 0, 'Le Parlement vote les lois et contrôle notamment le Gouvernement, les entreprises et services publics.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1571', 'Institutions & politique', 'Parlement', 'Comment les députés nationaux sont-ils élus ?', '["Au suffrage universel direct et secret", "Par les sénateurs", "Par les gouverneurs", "Par la Cour constitutionnelle"]'::jsonb, 0, 'L’article 101 prévoit leur élection au suffrage universel direct et secret.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1572', 'Institutions & politique', 'Parlement', 'Que représente juridiquement un sénateur congolais ?', '["Uniquement sa commune", "Sa province, tout en exerçant un mandat national", "Uniquement son parti", "Le Président de la République"]'::jsonb, 1, 'L’article 104 indique que le sénateur représente sa province, mais que son mandat est national.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1573', 'Institutions & politique', 'Parlement', 'Comment les sénateurs sont-ils élus en RDC ?', '["Directement par tous les électeurs", "Au second degré par les Assemblées provinciales", "Par le Président de la République", "Par les maires"]'::jsonb, 1, 'L’article 104 prévoit leur élection au second degré par les Assemblées provinciales.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1574', 'Institutions & politique', 'Parlement', 'Que devient de droit un ancien Président de la République élu, selon l’article 104 ?', '["Gouverneur à vie", "Sénateur à vie", "Député provincial à vie", "Juge constitutionnel à vie"]'::jsonb, 1, 'Les anciens Présidents de la République élus sont de droit sénateurs à vie.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1575', 'Institutions & politique', 'Institutions provinciales', 'Comment s’appellent les membres d’une Assemblée provinciale ?', '["Députés provinciaux", "Sénateurs locaux", "Conseillers nationaux", "Bourgmestres"]'::jsonb, 0, 'L’article 197 les appelle députés provinciaux.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1576', 'Institutions & politique', 'Institutions provinciales', 'Quel est le rôle principal de l’Assemblée provinciale ?', '["Délibérer dans les compétences provinciales et contrôler le Gouvernement provincial", "Élire directement le Président de la République", "Commander l’armée nationale", "Juger les crimes"]'::jsonb, 0, 'Elle délibère dans les matières provinciales, légifère par édit et contrôle le Gouvernement provincial.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1577', 'Institutions & politique', 'Institutions provinciales', 'Comment appelle-t-on le texte normatif adopté par une Assemblée provinciale dans son domaine de compétence ?', '["Une ordonnance-loi", "Un édit", "Un traité", "Un décret présidentiel"]'::jsonb, 1, 'L’Assemblée provinciale légifère par voie d’édit.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1578', 'Institutions & politique', 'Institutions provinciales', 'Qui élit le gouverneur et le vice-gouverneur d’une province ?', '["Les députés provinciaux", "Le Président de la République directement", "Tous les électeurs de la province au suffrage direct", "Les sénateurs uniquement"]'::jsonb, 0, 'Le gouverneur et le vice-gouverneur sont élus par les députés provinciaux.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1579', 'Institutions & politique', 'Institutions provinciales', 'Après leur élection, comment les gouverneur et vice-gouverneur sont-ils investis ?', '["Par ordonnance du Président de la République", "Par décret du bourgmestre", "Par arrêt de la Cour de cassation", "Par vote de l’Assemblée nationale"]'::jsonb, 0, 'L’article 198 prévoit leur investiture par ordonnance du Président de la République.', 'https://senat.cd/docs/CONSTITUTION%20DE%20LA%20RDC%20JOS.05.02.2011.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1580', 'Institutions & politique', 'Administration locale', 'Quelle autorité dirige une commune en RDC ?', '["Le bourgmestre", "Le sénateur", "Le procureur général", "Le député national"]'::jsonb, 0, 'La loi organique sur les entités territoriales décentralisées fait du bourgmestre l’autorité de la commune.', 'https://www.leganet.cd/Legislation/Droit%20Public/Administration.ter/L.08.16.17.10.2008.htm', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1581', 'Institutions & politique', 'Administration locale', 'Le bourgmestre est notamment officier de quoi dans sa commune ?', '["État civil", "Cour constitutionnelle", "Armée de l’air", "Banque centrale"]'::jsonb, 0, 'La loi prévoit notamment qu’il est officier de l’état civil et officier de police judiciaire à compétence générale.', 'https://www.leganet.cd/Legislation/Droit%20Public/Administration.ter/L.08.16.17.10.2008.htm', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1582', 'Institutions & politique', 'Administration locale', 'Quel niveau territorial un maire dirige-t-il principalement ?', '["Une ville", "Une province", "Un territoire national", "Une ambassade"]'::jsonb, 0, 'Dans l’organisation des entités territoriales décentralisées, le maire est l’autorité de la ville.', 'https://www.leganet.cd/Legislation/Droit%20Public/Administration.ter/L.08.16.17.10.2008.htm', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1583', 'Institutions & politique', 'Nationalité congolaise', 'Un enfant dont le père ou la mère est Congolais est-il Congolais d’origine selon la loi de 2004 ?', '["Oui", "Non, sauf s’il naît à Kinshasa", "Seulement si les deux parents sont Congolais", "Seulement après 18 ans"]'::jsonb, 0, 'La loi relative à la nationalité reconnaît comme Congolais d’origine l’enfant dont l’un des parents, père ou mère, est Congolais.', 'https://dgrad.gouv.cd/wp-content/uploads/2022/01/JUSTICE_Loi-004-024-du-12-nov-2004-relative-a-la-nationalite-congolaise.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1584', 'Institutions & politique', 'Nationalité congolaise', 'Cette règle selon laquelle la nationalité se transmet par un parent congolais correspond surtout à quel principe ?', '["Le droit du sang", "Le droit maritime", "Le droit fiscal", "Le droit diplomatique"]'::jsonb, 0, 'La filiation avec un parent congolais illustre le jus sanguinis, ou droit du sang.', 'https://dgrad.gouv.cd/wp-content/uploads/2022/01/JUSTICE_Loi-004-024-du-12-nov-2004-relative-a-la-nationalite-congolaise.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1585', 'Institutions & politique', 'Nationalité congolaise', 'Le simple fait de naître en RDC de deux parents étrangers donne-t-il automatiquement, dans tous les cas, la nationalité congolaise ?', '["Oui, toujours", "Non, la loi prévoit des règles et cas spécifiques ; il n’existe pas un droit du sol automatique et général", "Oui, dès la naissance quel que soit le statut des parents", "Oui, si l’enfant naît dans une capitale provinciale"]'::jsonb, 1, 'La loi ne prévoit pas un jus soli automatique et général. Elle organise toutefois des cas particuliers liés à la naissance sur le territoire.', 'https://dgrad.gouv.cd/wp-content/uploads/2022/01/JUSTICE_Loi-004-024-du-12-nov-2004-relative-a-la-nationalite-congolaise.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1586', 'Institutions & politique', 'Nationalité congolaise', 'Quelle situation peut conduire un nouveau-né trouvé en RDC à être présumé Congolais d’origine ?', '["Ses parents sont inconnus", "Il parle lingala", "Il vit à Kinshasa", "Il possède un passeport étranger"]'::jsonb, 0, 'La loi vise notamment le nouveau-né trouvé en RDC dont les parents sont inconnus.', 'https://dgrad.gouv.cd/wp-content/uploads/2022/01/JUSTICE_Loi-004-024-du-12-nov-2004-relative-a-la-nationalite-congolaise.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1587', 'Institutions & politique', 'Nationalité congolaise', 'La loi prévoit-elle un cas particulier pour un enfant né en RDC de parents apatrides ?', '["Oui", "Non, jamais", "Seulement s’il est majeur", "Uniquement sur décision du Sénat"]'::jsonb, 0, 'La loi relative à la nationalité prévoit notamment le cas de l’enfant né en RDC de parents apatrides.', 'https://dgrad.gouv.cd/wp-content/uploads/2022/01/JUSTICE_Loi-004-024-du-12-nov-2004-relative-a-la-nationalite-congolaise.pdf', null, null, 5, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1588', 'Institutions & politique', 'Droit de la famille', 'Quel est l’âge minimum légal du mariage pour l’homme comme pour la femme en RDC depuis la réforme de 2016 ?', '["16 ans", "17 ans", "18 ans", "21 ans"]'::jsonb, 2, 'L’article 352 fixe à 18 ans révolus l’âge minimum pour l’homme et la femme.', 'https://mail.leganet.cd/Legislation/Code%20de%20la%20famille/Loi.15.07.2016.html', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1589', 'Institutions & politique', 'Droit de la famille', 'Selon le Code de la famille, le consentement personnel des futurs époux est-il requis ?', '["Oui", "Non, seul le consentement des familles compte", "Seulement pour l’homme", "Seulement pour la femme"]'::jsonb, 0, 'L’article 351 impose le consentement personnel de chacun des futurs époux, sous réserve d’une représentation exceptionnellement autorisée par le juge pour juste motif.', 'https://mail.leganet.cd/Legislation/Code%20de%20la%20famille/Loi.15.07.2016.html', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1590', 'Institutions & politique', 'Droit de la famille', 'La dot peut-elle être symbolique en droit congolais ?', '["Oui", "Non, elle doit toujours avoir une valeur minimale nationale", "Seulement à Kinshasa", "Seulement si le mariage est religieux"]'::jsonb, 0, 'L’article 361 précise que, malgré toute coutume contraire, la dot peut être symbolique.', 'https://mail.leganet.cd/Legislation/Code%20de%20la%20famille/Loi.15.07.2016.html', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1591', 'Institutions & politique', 'Droit de la famille', 'Le mariage peut-il être célébré si aucune partie de la dot n’a été versée, selon l’article 361 ?', '["Oui dans tous les cas", "Non : la dot doit avoir été versée au moins en partie", "Oui si le bourgmestre l’autorise", "Oui seulement en province"]'::jsonb, 1, 'Le Code de la famille prévoit que la dot doit avoir été effectivement versée au moins en partie.', 'https://mail.leganet.cd/Legislation/Code%20de%20la%20famille/Loi.15.07.2016.html', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1592', 'Institutions & politique', 'Droit de la famille', 'En RDC, le divorce résulte juridiquement de quoi ?', '["D’une décision judiciaire", "D’une simple déclaration orale devant la famille", "D’un message adressé au bourgmestre", "D’une décision du Sénat"]'::jsonb, 0, 'L’article 546 prévoit que le divorce résulte d’une décision judiciaire prononçant la dissolution du mariage.', 'https://www.leganet.cd/Legislation/Code%20de%20la%20famille/CDF.2017.pdf', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1593', 'Institutions & politique', 'Droit de la famille', 'Une dissolution du mariage décidée uniquement par les autorités coutumières ou familiales produit-elle à elle seule l’effet juridique du divorce ?', '["Oui", "Non", "Oui uniquement le dimanche", "Oui si les deux familles signent"]'::jsonb, 1, 'L’article 547 précise que la dissolution par les autorités coutumières ou familiales est sans effet juridique à elle seule.', 'https://www.leganet.cd/Legislation/Code%20de%20la%20famille/CDF.2017.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1594', 'Institutions & politique', 'Droit de la famille', 'Sur quel fondement chacun des époux peut-il demander le divorce selon l’article 549 du Code de la famille ?', '["La destruction irrémédiable de l’union conjugale", "Un changement de profession", "Le déménagement dans une autre province", "La perte d’un emploi"]'::jsonb, 0, 'Le Code de la famille retient comme fondement la destruction irrémédiable de l’union conjugale.', 'https://www.leganet.cd/Legislation/Code%20de%20la%20famille/CDF.2017.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1595', 'Institutions & politique', 'Droit de la famille', 'Quand le tribunal peut-il considérer l’union conjugale comme irrémédiablement détruite ?', '["Lorsque la continuation de la vie conjugale et la sauvegarde du ménage sont devenues impossibles", "Dès le premier désaccord", "Seulement après 20 ans de mariage", "Uniquement si les familles le demandent"]'::jsonb, 0, 'L’article 550 demande au tribunal de tirer des faits la conviction que la continuation de la vie conjugale et la sauvegarde du ménage sont devenues impossibles.', 'https://www.leganet.cd/Legislation/Code%20de%20la%20famille/CDF.2017.pdf', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1596', 'Congo contemporain', 'Femmes et institutions', 'Quelle particularité historique Judith Suminwa Tuluka possède-t-elle depuis sa nomination du 1er avril 2024 ?', '["Elle est la première femme Première ministre de l’histoire de la RDC", "Elle est la première femme présidente de la République", "Elle est la première femme gouverneure de Kinshasa", "Elle est la première femme juge en RDC"]'::jsonb, 0, 'Judith Suminwa Tuluka est la première femme à exercer les fonctions de Première ministre en RDC.', 'https://www.primature.gouv.cd/primature/birographie-de-la-premiere-ministre/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1597', 'Congo contemporain', 'Femmes et institutions', 'Selon les données de l’Union interparlementaire mises à jour en juillet 2025, quelle part des 500 sièges de l’Assemblée nationale était occupée par des femmes ?', '["Environ 2,8 %", "Environ 12,8 %", "Environ 32,8 %", "Environ 52,8 %"]'::jsonb, 1, 'L’UIP indique 64 femmes sur 500 membres, soit 12,8 %, dans les données mises à jour en juillet 2025.', 'https://data.ipu.org/fr/parliament/CD/CD-LC01/data-on-women/', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1598', 'Institutions & politique', 'Lois emblématiques', 'Quelle loi congolaise de 2015 porte sur les modalités d’application des droits de la femme et de la parité ?', '["Loi n° 15/013 du 1er août 2015", "Loi n° 09/001 du 10 janvier 2009", "Loi n° 04/024 du 12 novembre 2004", "Loi n° 11/002 du 20 janvier 2011"]'::jsonb, 0, 'La loi n° 15/013 du 1er août 2015 porte sur les droits de la femme et la parité.', 'https://mail.leganet.cd/Legislation/Droit%20Public/DH/Loi.15.013.01.08.html', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1599', 'Institutions & politique', 'Lois emblématiques', 'Quelle loi congolaise de 2009 est consacrée à la protection de l’enfant ?', '["Loi n° 09/001 du 10 janvier 2009", "Loi n° 15/013 du 1er août 2015", "Loi n° 04/024 du 12 novembre 2004", "Loi n° 11/002 du 20 janvier 2011"]'::jsonb, 0, 'Il s’agit de la loi n° 09/001 du 10 janvier 2009 portant protection de l’enfant.', 'https://mail.leganet.cd/Legislation/JO/2009/L.09.001.10.01.09.htm', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1600', 'Personnages', 'Figures institutionnelles', 'Quelle fonction Jeanine Mabunda exerce-t-elle à partir du 24 avril 2019 ?', '["Présidente de l’Assemblée nationale", "Présidente de la Cour constitutionnelle", "Première ministre", "Gouverneure de Kinshasa"]'::jsonb, 0, 'Jeanine Mabunda est élue présidente du bureau définitif de l’Assemblée nationale en avril 2019.', 'https://www.radiookapi.net/2019/04/24/actualite/politique/rdc-jeanine-mabunda-place-le-controle-et-la-diplomatie-parlementaires', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1601', 'Personnages', 'Figures institutionnelles', 'Qui est élu président du Sénat de la RDC le 27 juillet 2019 ?', '["Alexis Thambwe Mwamba", "Martin Fayulu", "Olivier Kamitatu", "Jean-Marc Kabund"]'::jsonb, 0, 'Alexis Thambwe Mwamba est élu président du Sénat avec 65 voix sur 108 votants.', 'https://www.radiookapi.net/2019/07/27/actualite/politique/rdc-alexis-thambwe-elu-president-du-senat', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1602', 'Personnages', 'Figures institutionnelles', 'À qui Alexis Thambwe Mwamba succède-t-il à la présidence du Sénat en 2019 ?', '["Léon Kengo wa Dondo", "Joseph Kasa-Vubu", "Étienne Tshisekedi", "Jeanine Mabunda"]'::jsonb, 0, 'Il succède à Léon Kengo wa Dondo.', 'https://www.radiookapi.net/2019/07/27/actualite/politique/rdc-alexis-thambwe-elu-president-du-senat', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1603', 'Art, coutumes & patrimoine', 'Peuples et diversité', 'Combien de groupes ethniques compte approximativement la RDC selon plusieurs sources internationales ?', '["Moins de 20", "Environ 50", "Plus de 200", "Exactement 1 000"]'::jsonb, 2, 'Les sources internationales décrivent généralement la RDC comme un pays comptant plus de 200 groupes ethniques ; il s’agit d’une estimation, pas d’un décompte administratif figé.', 'https://www.dfat.gov.au/geo/congo-democratic-republic-of', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1604', 'Art, coutumes & patrimoine', 'Peuples et diversité', 'Pourquoi est-il préférable de dire « plus de 200 groupes ethniques » plutôt que de donner un chiffre exact et définitif ?', '["Parce que les classifications et estimations varient selon les sources", "Parce que la Constitution interdit de compter les communautés", "Parce qu’il n’existe qu’un seul peuple en RDC", "Parce que toutes les communautés sont identiques"]'::jsonb, 0, 'Les découpages ethnolinguistiques et les catégories utilisées varient selon les sources ; un chiffre arrondi est plus rigoureux qu’un total présenté comme absolu.', 'https://www.dfat.gov.au/geo/congo-democratic-republic-of', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1605', 'Sport', 'Coupe du monde 1974', 'Quel statut historique le Zaïre obtient-il en se qualifiant pour la Coupe du monde 1974 ?', '["Premier pays d’Afrique subsaharienne qualifié pour une phase finale de Coupe du monde", "Premier pays africain champion du monde", "Premier pays africain organisateur de la Coupe du monde", "Premier pays africain à battre le Brésil"]'::jsonb, 0, 'Le Zaïre devient le premier pays d’Afrique subsaharienne à atteindre une phase finale de Coupe du monde.', 'https://inside.fifa.com/news/leopards-roar-germany-1974-771439', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1606', 'Sport', 'Coupe du monde 1974', 'Quel pays le Zaïre bat-il 3-0 à Kinshasa en décembre 1973 lors d’un match décisif des qualifications au Mondial 1974 ?', '["Maroc", "Égypte", "Cameroun", "Ghana"]'::jsonb, 0, 'Le Zaïre bat le Maroc 3-0 au Stade Tata Raphaël lors de cette campagne qualificative.', 'https://inside.fifa.com/news/leopards-roar-germany-1974-771439', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1607', 'Sport', 'Coupe du monde 1974', 'Quel est le score du match Écosse–Zaïre au Mondial 1974 ?', '["1-0", "2-0", "3-0", "4-0"]'::jsonb, 1, 'L’Écosse bat le Zaïre 2-0 lors de la phase de groupes.', 'https://inside.fifa.com/news/leopards-roar-germany-1974-771439', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1608', 'Sport', 'Coupe du monde 1974', 'Quel est le score du match Zaïre–Brésil au Mondial 1974 ?', '["0-1", "0-2", "0-3", "1-3"]'::jsonb, 2, 'Le Brésil s’impose 3-0 contre le Zaïre.', 'https://inside.fifa.com/news/leopards-roar-germany-1974-771439', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1609', 'Sport', 'Coupe du monde 1974', 'Quel joueur yougoslave inscrit un triplé lors du 9-0 contre le Zaïre au Mondial 1974 ?', '["Dušan Bajević", "Johan Cruyff", "Franz Beckenbauer", "Gerd Müller"]'::jsonb, 0, 'Dušan Bajević inscrit trois buts contre le Zaïre.', 'https://www.fifa.com/fr/tournaments/mens/worldcup/articles/plus-gros-ecarts-mi-temps', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1610', 'Sport', 'Coupe du monde 1974', 'Combien de buts le Zaïre marque-t-il au total lors de ses trois matchs de poule du Mondial 1974 ?', '["0", "1", "2", "3"]'::jsonb, 0, 'Le Zaïre perd 0-2 contre l’Écosse, 0-9 contre la Yougoslavie et 0-3 contre le Brésil : aucun but marqué.', 'https://inside.fifa.com/news/leopards-roar-germany-1974-771439', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1611', 'Gastronomie', 'Boissons et marques', 'Laquelle de ces marques de bière est historiquement associée à la Bralima en RDC ?', '["Primus", "Guinness Foreign Extra uniquement", "Tusker uniquement", "Castle Lite uniquement"]'::jsonb, 0, 'Primus figure parmi les marques emblématiques de la Bralima en RDC.', 'https://bralima.net/nos-marques/nos-bieres/', null, null, 1, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1612', 'Gastronomie', 'Boissons et marques', 'En quelle année la Brasserie de Léopoldville met-elle sur le marché sa première bouteille de Primus, selon l’histoire publiée par Bralima ?', '["1910", "1926", "1960", "1997"]'::jsonb, 1, 'Bralima situe la première mise en bouteille de Primus en 1926.', 'https://bralima.net/notre-societe/notre-histoire/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1613', 'Gastronomie', 'Boissons et marques', 'Laquelle de ces bières appartient également au portefeuille de Bralima en RDC ?', '["Turbo King", "Skol uniquement", "Tusker", "Flag"]'::jsonb, 0, 'Bralima commercialise notamment Primus, Turbo King, Mützig et d’autres marques.', 'https://bralima.net/nos-marques/nos-bieres/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1614', 'Gastronomie', 'Boissons et marques', 'Quelle entreprise brassicole congolaise fondée à Kinshasa en 1923 produit notamment Primus ?', '["Bralima", "SNCC", "Gécamines", "RVA"]'::jsonb, 0, 'La Bralima est fondée à Kinshasa en 1923 et produit notamment Primus.', 'https://bralima.net/notre-societe/notre-histoire/', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1615', 'Gastronomie', 'Boissons et marques', 'Laquelle de ces marques de bière est également commercialisée en RDC par Bracongo ?', '["Skol", "Primus", "Heineken exclusivement", "Maltina"]'::jsonb, 0, 'Skol fait partie des marques présentes dans le portefeuille de Bracongo en RDC.', 'https://bracongo.cd/wp-content/uploads/2018/02/Prix-Pierre-Castel-RDC-2024-Communique-de-presse-Grand-Oral-2.pdf', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1616', 'Gastronomie', 'Boissons et marques', 'Quelle bière lancée à Kinshasa en 2010 est présentée par Bracongo comme liée à l’« esprit kinois » ?', '["Nkoyi Blonde", "Primus", "Turbo King", "Mützig"]'::jsonb, 0, 'Bracongo situe le lancement de Nkoyi Blonde à Kinshasa en 2010 et la présente comme une marque fortement associée à la culture kinoise.', 'https://bracongo.cd/Boisson/nkoyi-blonde', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1617', 'Congo contemporain', 'Églises de réveil et cultes', 'En mai 2026, combien d’associations confessionnelles disposaient approximativement de la personnalité juridique en RDC selon le ministre de la Justice ?', '["Environ 1 900", "Environ 19 000", "Environ 190 000", "Exactement 30 000"]'::jsonb, 1, 'Le ministre de la Justice a évoqué environ 19 000 associations confessionnelles disposant de la personnalité juridique. Ce chiffre concerne l’ensemble des associations confessionnelles reconnues, pas uniquement les églises de réveil.', 'https://acp.cd/nation/rdc-19-000-associations-confessionnelles-officiellement-operationnelles-et-plus-de-30-000-requetes-sous-traitement-ministre-de-la-justice-au-senat/', null, null, 2, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1618', 'Congo contemporain', 'Églises de réveil et cultes', 'En mai 2026, combien de demandes de reconnaissance d’associations confessionnelles étaient encore en cours de traitement selon le ministère de la Justice ?', '["Moins de 500", "Environ 3 000", "Plus de 30 000", "Plus d’un million"]'::jsonb, 2, 'Le ministère a indiqué que plus de 30 000 requêtes étaient encore en cours de traitement.', 'https://acp.cd/nation/rdc-19-000-associations-confessionnelles-officiellement-operationnelles-et-plus-de-30-000-requetes-sous-traitement-ministre-de-la-justice-au-senat/', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1619', 'Congo contemporain', 'Églises de réveil et cultes', 'Le gouvernement congolais dispose-t-il d’un nombre officiel exact de tous les pasteurs exerçant en RDC ?', '["Oui, exactement 19 000", "Oui, exactement 30 000", "Non, le ministre a indiqué qu’un nombre précis ne pouvait pas être donné", "Oui, mais le chiffre est secret"]'::jsonb, 2, 'Le ministre de la Justice a expliqué qu’il était impossible de donner un nombre officiel précis de pasteurs.', 'https://www.radiookapi.net/node/283608', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1620', 'Congo contemporain', 'Églises de réveil et cultes', 'Peut-on affirmer qu’il existe exactement 19 000 « églises de réveil » en RDC ?', '["Oui", "Non, les 19 000 désignent les associations confessionnelles reconnues toutes confessions confondues", "Oui, uniquement à Kinshasa", "Oui, et aucune autre confession n’est comptée"]'::jsonb, 1, 'Le chiffre de 19 000 porte sur l’ensemble des associations confessionnelles reconnues, pas uniquement les églises de réveil.', 'https://acp.cd/nation/rdc-19-000-associations-confessionnelles-officiellement-operationnelles-et-plus-de-30-000-requetes-sous-traitement-ministre-de-la-justice-au-senat/', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1621', 'Institutions & politique', 'Droit des cultes', 'Sous quelle forme juridique une association confessionnelle doit-elle se constituer en RDC selon la loi n° 004/2001 ?', '["Une société commerciale", "Une ASBL dotée de la personnalité juridique", "Un parti politique", "Une entreprise publique"]'::jsonb, 1, 'L’article 48 de la loi n° 004/2001 prévoit une ASBL dotée de la personnalité juridique.', 'https://www.droitcongolais.be/Legislation/Droit%20Public/loi0042001.20.07.2001.asbl.htm', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1622', 'Institutions & politique', 'Droit des cultes', 'Quel âge minimum la loi n° 004/2001 exige-t-elle notamment pour être fondateur d’une association confessionnelle en RDC ?', '["18 ans", "21 ans", "25 ans", "30 ans"]'::jsonb, 3, 'L’article 49 fixe notamment l’âge minimum à 30 ans.', 'https://www.droitcongolais.be/Legislation/Droit%20Public/loi0042001.20.07.2001.asbl.htm', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1623', 'Institutions & politique', 'Droit des cultes', 'Quelle formation est notamment exigée du représentant légal d’une association confessionnelle par la loi n° 004/2001 ?', '["Un diplôme supérieur ou universitaire en matières religieuses ou niveau équivalent", "Un diplôme de médecine", "Un mandat parlementaire", "Un brevet militaire"]'::jsonb, 0, 'L’article 50 exige notamment un diplôme supérieur ou universitaire, ou niveau équivalent, en matières religieuses.', 'https://www.droitcongolais.be/Legislation/Droit%20Public/loi0042001.20.07.2001.asbl.htm', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1624', 'Institutions & politique', 'Droit des cultes', 'Une association confessionnelle peut-elle légalement imposer des pratiques portant atteinte à la vie ou à la santé de ses membres ?', '["Oui", "Non", "Oui si le pasteur le décide", "Oui uniquement la nuit"]'::jsonb, 1, 'L’article 52 interdit notamment les pratiques pouvant porter atteinte à la vie ou à la santé.', 'https://www.droitcongolais.be/Legislation/Droit%20Public/loi0042001.20.07.2001.asbl.htm', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1625', 'Institutions & politique', 'Droit des cultes', 'Le ministre de la Justice peut-il suspendre temporairement une association confessionnelle dont l’activité menace la sécurité de l’État ?', '["Oui, dans les conditions prévues par la loi", "Non, jamais", "Seulement avec l’accord d’une ambassade", "Uniquement si elle est catholique"]'::jsonb, 0, 'La loi n° 004/2001 prévoit une suspension temporaire et, selon les cas, une procédure judiciaire de dissolution.', 'https://www.droitcongolais.be/Legislation/Droit%20Public/loi0042001.20.07.2001.asbl.htm', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1626', 'Institutions & politique', 'Droit des cultes', 'En 2024, quelle distance minimale avait été annoncée pour l’installation de nouvelles associations confessionnelles les unes par rapport aux autres ?', '["50 mètres", "100 mètres", "500 mètres", "5 kilomètres"]'::jsonb, 2, 'La mesure annoncée en juillet 2024 fixait un rayon de 500 mètres pour les nouvelles installations.', 'https://www.radiookapi.net/2024/07/23/emissions/parole-aux-auditeurs/comment-la-justice-congolaise-peut-elle-reguler-le', null, null, 3, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1627', 'Institutions & politique', 'Droit des cultes', 'En 2026, que décide le ministre de la Justice Guillaume Ngefa concernant le « permis de culte » instauré auparavant ?', '["Il le rend obligatoire à vie", "Il le supprime en le jugeant dépourvu de fondement légal", "Il le réserve aux catholiques", "Il le transforme en passeport"]'::jsonb, 1, 'En mai 2026, le ministre a réitéré sa suppression, estimant qu’aucune loi ne l’imposait comme condition à l’exercice du culte.', 'https://acp.cd/affaire-judiciare-et-droits-humains/la-rdc-reitere-sa-decision-de-supprimer-les-permis-de-culte/', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1628', 'Institutions & politique', 'Droit des cultes', 'Après la suppression du « permis de culte » en 2026, quelle exigence juridique reste centrale pour une association confessionnelle ?', '["La personnalité juridique conformément à la loi", "Un mandat de député", "L’adhésion obligatoire à l’ERC", "L’accord d’une ambassade"]'::jsonb, 0, 'La reconnaissance juridique de l’association demeure régie par la loi sur les ASBL confessionnelles.', 'https://acp.cd/affaire-judiciare-et-droits-humains/la-rdc-reitere-sa-decision-de-supprimer-les-permis-de-culte/', null, null, 4, 'valide') on conflict (id) do nothing;
insert into question (id, categorie, sous_categorie, enonce, reponses, bonne_reponse, explication, source_url, image_id, image_alt, difficulte, statut) values ('RLC-1629', 'Congo contemporain', 'Églises de réveil et cultes', 'Quel document appelé F92 a fait l’objet d’une suppression dans l’encadrement administratif des associations confessionnelles ?', '["Un accusé de réception pour des structures en attente de personnalité juridique", "Un diplôme de théologie", "Un passeport religieux", "Une carte d’électeur"]'::jsonb, 0, 'Le F92 servait d’accusé de réception à des structures en attente de personnalité juridique.', 'https://www.radiookapi.net/2024/07/01/actualite/societe/suppression-du-f92-lerc-salue-la-demarche-du-ministre-de-la-justice', null, null, 4, 'valide') on conflict (id) do nothing;
